import type { CommandDefinition, VirtualShellPlugin } from "../../contracts/index.js";
import { createTreeCommand } from "./tree.js";
import type { TreeCommandsOptions } from "./options.js";
export { createTreeCommand } from "./tree.js";
export type { TreeCommandsOptions, TreeLimits } from "./options.js";

export function createTreeCommands(options: TreeCommandsOptions = {}): readonly CommandDefinition[] {
  return [createTreeCommand(options)];
}

export function treeCommands(options: TreeCommandsOptions = {}): VirtualShellPlugin {
  const commands = createTreeCommands(options);
  const replace = options.replace ?? false;
  return { name: "tree-commands", setup(host) {
    if (!replace) for (const command of commands) {
      if (host.commands.has(command.name)) throw new Error(`Command already registered: ${command.name}`);
    }
    for (const command of commands) host.commands.register(command, { replace });
  } };
}

import { FsError, resolvePath, type CommandDefinition, type FileStat } from "../../contracts/index.js";
import { compareObservedEntries } from "../copy-identity.js";
import { parse, help, type Arguments } from "./arguments.js";
import { escaped, message, TreeLimitError, UsageError, WalkBudget } from "./io.js";
import { settings, type TreeCommandsOptions } from "./options.js";
import { matches } from "./pattern.js";

interface Entry {
  readonly path: string;
  readonly display: string;
  readonly name: string;
  stat?: FileStat;
  followed?: FileStat;
  target?: string;
  error?: string;
  cycle?: boolean;
}

function directory(entry: Entry): boolean { return (entry.followed ?? entry.stat)?.type === "directory"; }

function serialized(value: unknown): string {
  return JSON.stringify(value).replace(/[\u007f-\u009f\u2028\u2029\p{Cf}]/gu,
    character => character.split("").map(unit => `\\u${unit.charCodeAt(0).toString(16).padStart(4, "0")}`).join(""));
}

class Walker {
  private directories = 0;
  private files = 0;
  private failed = false;
  constructor(private readonly budget: WalkBudget, private readonly args: Arguments) {}

  async inspect(path: string, display: string, name: string): Promise<Entry> {
    const { context } = this.budget;
    const options = { signal: context.signal };
    const entry: Entry = { path, display, name };
    this.budget.text(path);
    this.budget.text(display);
    try {
      entry.stat = await this.budget.fs(() => context.fs.lstat(path, options));
      if (entry.stat.type === "symlink") {
        if (!context.fs.readlink) throw new FsError("ENOTSUP", { path, syscall: "readlink" });
        entry.target = await this.budget.fs(() => context.fs.readlink!(path, options));
        try { entry.followed = await this.budget.fs(() => context.fs.stat(path, options)); }
        catch (error) {
          context.signal.throwIfAborted();
          if (!(error instanceof FsError) || (error.code !== "ENOENT" && error.code !== "ENOTDIR")) throw error;
        }
      }
    } catch (error) {
      context.signal.throwIfAborted();
      if (error instanceof TreeLimitError) throw error;
      entry.error = message(error);
    }
    if (entry.target !== undefined) this.budget.text(entry.target);
    return entry;
  }

  async children(entry: Entry, ancestors: readonly Entry[], depth: number): Promise<Entry[]> {
    const { context, limits } = this.budget;
    if (entry.error || !directory(entry) || (entry.stat?.type === "symlink" && !this.args.follow)) return [];
    if (depth === this.args.level) return [];
    this.budget.check(depth + 1, limits.maxDepth, "depth");
    let listing;
    try {
      for (const ancestor of ancestors) {
        const same = await this.budget.fs(() => compareObservedEntries(context.fs, entry.path, (entry.followed ?? entry.stat)!,
          context.fs, ancestor.path, (ancestor.followed ?? ancestor.stat)!, { signal: context.signal }));
        if (same === "same") { entry.cycle = true; return []; }
      }
      listing = await this.budget.fs(() => context.fs.readdir(entry.path, { signal: context.signal }));
    } catch (error) {
      context.signal.throwIfAborted();
      if (error instanceof TreeLimitError) throw error;
      entry.error = message(error); return [];
    }
    this.budget.check(listing.length, limits.maxDirectoryEntries, "directory entry");
    this.budget.entry(listing.length);
    const names = new Set<string>();
    const candidates: { name: string; bytes: Uint8Array }[] = [];
    for (const item of listing) {
      this.budget.step();
      this.budget.text(item.name);
      if (item.name === "." || item.name === "..") continue;
      if (!item.name || item.name.includes("/") || item.name.includes("\0") || /[\ud800-\udfff]/u.test(item.name) || names.has(item.name)) {
        entry.error = "invalid or duplicate directory entry"; return [];
      }
      names.add(item.name);
      if (!this.args.all && item.name.startsWith(".")) continue;
      const bytes = new TextEncoder().encode(item.name);
      if (this.args.exclude.some(pattern => matches(pattern, bytes, this.budget))) continue;
      candidates.push({ name: item.name, bytes });
    }
    candidates.sort((left, right) => {
      this.budget.step();
      return Buffer.compare(left.bytes, right.bytes) * (this.args.reverse ? -1 : 1);
    });
    const children: Entry[] = [];
    for (const item of candidates) {
      const child = await this.inspect(resolvePath(entry.path, item.name), `${entry.display.replace(/\/$/u, "")}/${item.name}`, item.name);
      if (!child.error) {
        if (this.args.directories && !directory(child)) continue;
        const includeDirectory = child.stat?.type === "directory" || (this.args.follow && directory(child));
        if (!includeDirectory && this.args.include.length && !this.args.include.some(pattern => matches(pattern, item.bytes, this.budget))) continue;
      }
      children.push(child);
    }
    if (this.args.dirsFirst) children.sort((left, right) => Number(directory(right)) - Number(directory(left)));
    return children;
  }

  async visit(entry: Entry, ancestors: readonly Entry[], prefix: string, last: boolean, depth: number): Promise<void> {
    const children = await this.children(entry, ancestors, depth);
    if (directory(entry)) { if (depth > 0 || children.length) this.directories++; }
    else if (entry.stat) this.files++;
    if (entry.error) {
      this.budget.text(entry.error);
      this.failed = true;
      await this.budget.emit(this.budget.context.stderr, `tree: ${escaped(entry.display)}: ${escaped(entry.error)}\n`);
    }
    const name = depth === 0 || this.args.full ? entry.display : entry.name;
    const annotation = entry.error ?? (entry.cycle ? "recursive, not followed" : undefined);
    if (this.args.json) {
      const fields = { type: entry.stat?.type === "symlink" ? "link" : entry.stat?.type ?? "unknown", name,
        ...(entry.target === undefined ? {} : { target: entry.target }), ...(annotation === undefined ? {} : { error: annotation }) };
      await this.write(`${this.padding(depth + 1)}${serialized(fields).slice(0, -1)}`);
      if (children.length) {
        await this.write(`,"contents":[${this.newline()}`);
        for (let index = 0; index < children.length; index++) {
          if (index) await this.write(`,${this.newline()}`);
          await this.visit(children[index]!, [...ancestors, entry], "", index === children.length - 1, depth + 1);
        }
        await this.write(`${this.newline()}${this.padding(depth + 1)}]`);
      }
      await this.write("}");
    } else {
      const utf8 = this.args.charset === "UTF-8";
      const branch = this.args.indent && depth > 0 ? prefix + (last ? (utf8 ? "└── " : "`-- ") : (utf8 ? "├── " : "|-- ")) : "";
      await this.write(`${branch}${escaped(name)}${entry.target === undefined ? "" : ` -> ${escaped(entry.target)}`}${annotation === undefined ? "" : `  [${escaped(annotation)}]`}\n`);
      const childPrefix = depth === 0 ? "" : prefix + (last ? "    " : utf8 ? "│   " : "|   ");
      for (let index = 0; index < children.length; index++) {
        await this.visit(children[index]!, [...ancestors, entry], childPrefix, index === children.length - 1, depth + 1);
      }
    }
  }

  private newline(): string { return this.args.indent ? "\n" : ""; }
  private padding(depth: number): string { return this.args.indent ? "  ".repeat(depth) : ""; }
  private write(value: string): Promise<void> { return this.budget.emit(this.budget.context.stdout, value); }

  async run(): Promise<number> {
    if (this.args.json) await this.write(`[${this.newline()}`);
    for (let index = 0; index < this.args.operands.length; index++) {
      const operand = this.args.operands[index]!;
      this.budget.entry();
      if (this.args.json && index) await this.write(`,${this.newline()}`);
      const entry = await this.inspect(resolvePath(this.budget.context.cwd, operand), operand, operand);
      await this.visit(entry, [], "", true, 0);
    }
    if (this.args.report) {
      if (this.args.json) {
        await this.write(`,${this.newline()}${this.padding(1)}${serialized({ type: "report", directories: this.directories,
          ...(this.args.directories ? {} : { files: this.files }) })}`);
      } else await this.write(`\n${this.directories} ${this.directories === 1 ? "directory" : "directories"}${this.args.directories ? "" : `, ${this.files} ${this.files === 1 ? "file" : "files"}`}\n`);
    }
    if (this.args.json) await this.write(`${this.newline()}]\n`);
    return this.failed ? 1 : 0;
  }
}

export function createTreeCommand(options: TreeCommandsOptions = {}): CommandDefinition {
  const limits = settings(options);
  return { name: "tree", description: "List a bounded virtual directory tree", async execute(context) {
    const budget = new WalkBudget(context, limits);
    let args: Arguments;
    try { args = parse(context.args, budget); }
    catch (error) {
      context.signal.throwIfAborted();
      if (!(error instanceof UsageError)) throw error;
      await budget.emit(context.stderr, `tree: ${escaped(error.message)}\n`);
      return { exitCode: 2 };
    }
    if (args.help || args.version) {
      await budget.emit(context.stdout, args.help ? help : "tree (virtual-bash bounded profile) 1\n");
      return { exitCode: 0 };
    }
    return { exitCode: await new Walker(budget, args).run() };
  } };
}

export * from "./command.js";
export * from "./errors.js";
export * from "./filesystem.js";
export * from "./io.js";
export * from "./path.js";
export * from "./plugin.js";

import { FsError, type EntryComparison, type FileStat, type FileSystem, type FsOptions } from "../contracts/index.js";

function complete(stat: FileStat): boolean {
  return ((typeof stat.identityScope === "object" && stat.identityScope !== null) || typeof stat.identityScope === "symbol")
    && typeof stat.dev === "number" && Number.isSafeInteger(stat.dev) && stat.dev >= 0
    && typeof stat.ino === "number" && Number.isSafeInteger(stat.ino) && stat.ino >= 0;
}

export function compareCopyIdentity(left: FileStat | undefined, right: FileStat | undefined): "same" | "distinct" | "unknown" {
  if (!left || !right || !complete(left) || !complete(right)) return "unknown";
  return left.identityScope === right.identityScope && left.dev === right.dev && left.ino === right.ino ? "same" : "distinct";
}

export async function compareObservedEntries(
  fs: FileSystem, path: string, stat: FileStat,
  peer: FileSystem, peerPath: string, peerStat: FileStat,
  options: FsOptions = {},
): Promise<EntryComparison> {
  options.signal?.throwIfAborted();
  const identity = compareCopyIdentity(stat, peerStat);
  if (identity !== "unknown") return identity;
  let result: EntryComparison = "unknown";
  const operands: readonly [FileSystem, string, FileSystem, string][] = fs === peer
    ? [[fs, path, peer, peerPath]]
    : [[fs, path, peer, peerPath], [peer, peerPath, fs, path]];
  for (const [owner, ownPath, other, otherPath] of operands) {
    options.signal?.throwIfAborted();
    if (!owner.compareEntry) continue;
    let answer: EntryComparison;
    try { answer = await owner.compareEntry(ownPath, other, otherPath, options); }
    catch (error) { options.signal?.throwIfAborted(); throw error; }
    options.signal?.throwIfAborted();
    if (answer !== "same" && answer !== "distinct" && answer !== "unknown") {
      throw new FsError("EIO", { path, dest: peerPath, message: "invalid entry comparison answer" });
    }
    if (answer === "unknown") continue;
    if (result !== "unknown" && result !== answer) {
      throw new FsError("EIO", { path, dest: peerPath, message: "conflicting entry comparison answers" });
    }
    result = answer;
  }
  return result;
}

import { setImmediate as yieldTurn } from "node:timers/promises";
import { FsError, writeBytes, type ByteSink, type CommandContext } from "../../contracts/index.js";
import type { TreeLimits } from "./options.js";

export class UsageError extends Error {}

export class TreeLimitError extends FsError {
  constructor(label: string, maximum: number) {
    super("EFBIG", { message: `tree ${label} limit exceeded (${maximum})` });
  }
}

export function message(error: unknown): string {
  return error instanceof Error ? error.message.replace(/^[A-Z][A-Z0-9]+: /u, "") : String(error);
}

export function escaped(value: string): string {
  const controls: Record<number, string> = { 8: "\\b", 9: "\\t", 10: "\\n", 11: "\\v", 12: "\\f", 13: "\\r", 92: "\\\\" };
  let result = "";
  for (const byte of new TextEncoder().encode(value)) {
    result += controls[byte] ?? (byte >= 32 && byte < 127 ? String.fromCharCode(byte) : `\\${byte.toString(8).padStart(3, "0")}`);
  }
  return result;
}

export class WalkBudget {
  private entries = 0;
  private metadata = 0;
  private output = 0;
  private steps = 0;
  private operations = 0;
  constructor(readonly context: CommandContext, readonly limits: TreeLimits) {}

  check(value: number, maximum: number, label: string): void {
    this.context.signal.throwIfAborted();
    if (value > maximum) throw new TreeLimitError(label, maximum);
  }

  step(count = 1): void { this.check(this.steps += count, this.limits.maxSteps, "work"); }

  entry(count = 1): void { this.check(this.entries += count, this.limits.maxEntries, "entry"); }

  text(value: string): void {
    const size = Buffer.byteLength(value);
    this.check(size, this.limits.maxPathBytes, "path/name");
    this.check(this.metadata += size, this.limits.maxMetadataBytes, "metadata");
  }

  async fs<Result>(operation: () => Promise<Result>): Promise<Result> {
    this.step();
    const { signal } = this.context;
    if (++this.operations % 64 === 0) await yieldTurn(undefined, { signal });
    signal.throwIfAborted();
    let abort!: () => void;
    const aborted = new Promise<never>((_resolve, reject) => {
      abort = () => reject(signal.reason);
      signal.addEventListener("abort", abort, { once: true });
    });
    try {
      const result = await Promise.race([Promise.resolve().then(() => {
        signal.throwIfAborted();
        return operation();
      }), aborted]);
      signal.throwIfAborted();
      return result;
    } finally { signal.removeEventListener("abort", abort); }
  }

  async emit(sink: ByteSink, value: string): Promise<void> {
    const size = Buffer.byteLength(value);
    this.check(this.output + size, this.limits.maxOutputBytes, "output");
    this.output += size;
    const bytes = new TextEncoder().encode(value);
    for (let offset = 0; offset < bytes.length; offset += 16384) {
      await writeBytes(sink, bytes.slice(offset, offset + 16384), this.context.signal);
      this.context.signal.throwIfAborted();
    }
  }
}

import { UsageError, type WalkBudget } from "./io.js";
import { compile, type Pattern } from "./pattern.js";

export interface Arguments {
  all: boolean;
  directories: boolean;
  follow: boolean;
  full: boolean;
  indent: boolean;
  json: boolean;
  report: boolean;
  reverse: boolean;
  dirsFirst: boolean;
  charset: "ASCII" | "UTF-8";
  level: number | undefined;
  include: Pattern[];
  exclude: Pattern[];
  operands: string[];
  help: boolean;
  version: boolean;
}

export function parse(args: readonly string[], budget: WalkBudget): Arguments {
  budget.check(args.length, budget.limits.maxArguments, "argument count");
  let bytes = 0;
  for (const arg of args) {
    budget.check(bytes += Buffer.byteLength(arg), budget.limits.maxArgumentBytes, "argument");
    if (arg.includes("\0")) throw new UsageError("arguments must not contain NUL");
    if (/[\ud800-\udfff]/u.test(arg)) throw new UsageError("arguments must be well-formed Unicode");
  }
  const result: Arguments = { all: false, directories: false, follow: false, full: false, indent: true,
    json: false, report: true, reverse: false, dirsFirst: false, charset: "ASCII", level: undefined,
    include: [], exclude: [], operands: [], help: false, version: false };
  let ended = false;
  for (let index = 0; index < args.length; index++) {
    const arg = args[index]!;
    const value = (option: string, attached: string | undefined): string => {
      if (attached !== undefined) return attached;
      if (++index >= args.length) throw new UsageError(`${option} requires a value`);
      return args[index]!;
    };
    if (ended || !arg.startsWith("-") || arg === "-") { result.operands.push(arg); continue; }
    if (arg === "--") { ended = true; continue; }
    if (arg === "--noreport") { result.report = false; continue; }
    if (arg === "--dirsfirst") { result.dirsFirst = true; continue; }
    if (arg === "--help") { result.help = true; continue; }
    if (arg === "--version") { result.version = true; continue; }
    if (arg === "--charset" || arg.startsWith("--charset=")) {
      const charset = value("--charset", arg.startsWith("--charset=") ? arg.slice(10) : undefined).toUpperCase();
      if (charset !== "ASCII" && charset !== "UTF-8") throw new UsageError("supported charsets: ASCII, UTF-8");
      result.charset = charset; continue;
    }
    if (arg.startsWith("--")) throw new UsageError(`unsupported option: ${arg}`);
    for (let offset = 1; offset < arg.length; offset++) {
      const flag = arg[offset]!;
      switch (flag) {
        case "a": result.all = true; break;
        case "d": result.directories = true; break;
        case "l": result.follow = true; break;
        case "f": result.full = true; break;
        case "i": result.indent = false; break;
        case "J": result.json = true; break;
        case "r": result.reverse = true; break;
        case "n": break;
        case "L": case "P": case "I": {
          const argument = value(`-${flag}`, offset + 1 < arg.length ? arg.slice(offset + 1) : undefined);
          if (flag === "L") {
            const level = Number(argument);
            if (!/^[0-9]+$/u.test(argument) || !Number.isSafeInteger(level) || level < 1 || level > budget.limits.maxDepth) {
              throw new UsageError(`-L must be between 1 and ${budget.limits.maxDepth}`);
            }
            result.level = level;
          } else (flag === "P" ? result.include : result.exclude).push(compile(argument));
          offset = arg.length; break;
        }
        default: throw new UsageError(`unsupported option: -${flag}`);
      }
    }
  }
  if (!result.operands.length) result.operands.push(".");
  for (const operand of result.operands) if (operand === "") throw new UsageError("empty path operand");
  return result;
}

export const help = `Usage: tree [-adlfirnJ] [-L depth] [-P pattern] [-I pattern] [--dirsfirst]
            [--charset=ASCII|UTF-8] [--noreport] [--] [path ...]
Virtual filesystem tree; no native processes or implicit host access.
Default: visible entries, no symlink traversal, C/UTF-8-byte name order,
ASCII branches, escaped filenames. -l follows directory links; ancestor
cycles are skipped. -P includes files; -I excludes files and directories.
Basename patterns: *, ?, bracket ranges, | alternatives, backslash literals.
-J emits JSON; -i removes text branches or JSON formatting whitespace.
Unsupported options and path/globstar patterns are rejected before VFS I/O.
`;

export interface TreeLimits {
  readonly maxArguments: number;
  readonly maxArgumentBytes: number;
  readonly maxEntries: number;
  readonly maxDirectoryEntries: number;
  readonly maxDepth: number;
  readonly maxPathBytes: number;
  readonly maxMetadataBytes: number;
  readonly maxOutputBytes: number;
  readonly maxSteps: number;
}

export interface TreeCommandsOptions {
  readonly replace?: boolean;
  readonly limits?: Partial<TreeLimits>;
}

export function settings(options: TreeCommandsOptions): TreeLimits {
  const limits: TreeLimits = {
    maxArguments: 4096, maxArgumentBytes: 65536, maxEntries: 100000,
    maxDirectoryEntries: 10000, maxDepth: 256, maxPathBytes: 16384,
    maxMetadataBytes: 8 * 1024 * 1024, maxOutputBytes: 16 * 1024 * 1024,
    maxSteps: 4 * 1024 * 1024, ...options.limits,
  };
  for (const [name, value] of Object.entries(limits)) {
    if (!Number.isSafeInteger(value) || value < 1) throw new RangeError(`Invalid tree limit: ${name}`);
  }
  return Object.freeze(limits);
}

import { UsageError, type WalkBudget } from "./io.js";

type Token = number | "*" | "?" | { readonly negate: boolean; readonly ranges: readonly (readonly [number, number])[] };
export type Pattern = readonly (readonly Token[])[];

export function compile(pattern: string): Pattern {
  if (pattern.includes("/") || pattern.includes("**")) throw new UsageError("path patterns and ** are not supported; use basename patterns");
  const bytes = new TextEncoder().encode(pattern);
  const alternatives: Token[][] = [[]];
  let tokens = alternatives[0]!;
  for (let index = 0; index < bytes.length; index++) {
    const byte = bytes[index]!;
    if (byte === 124) { tokens = []; alternatives.push(tokens); }
    else if (byte === 42) tokens.push("*");
    else if (byte === 63) tokens.push("?");
    else if (byte === 92) {
      if (++index === bytes.length) throw new UsageError("trailing backslash in pattern");
      tokens.push(bytes[index]!);
    } else if (byte === 91) {
      index++;
      const negate = bytes[index] === 94 || bytes[index] === 33;
      if (negate) index++;
      const ranges: [number, number][] = [];
      while (index < bytes.length && (bytes[index] !== 93 || ranges.length === 0)) {
        const start = bytes[index++]!;
        let end = start;
        if (bytes[index] === 45 && bytes[index + 1] !== 93 && index + 1 < bytes.length) {
          end = bytes[index + 1]!; index += 2;
        }
        if (end < start) throw new UsageError("descending range in pattern");
        ranges.push([start, end]);
      }
      if (bytes[index] !== 93 || ranges.length === 0) throw new UsageError("unclosed or empty bracket pattern");
      tokens.push({ negate, ranges });
    } else tokens.push(byte);
  }
  return alternatives;
}

export function matches(pattern: Pattern, name: Uint8Array, budget: WalkBudget): boolean {
  for (const tokens of pattern) {
    let previous = new Uint8Array(name.length + 1);
    previous[0] = 1;
    for (const token of tokens) {
      budget.step(name.length + 1);
      const next = new Uint8Array(name.length + 1);
      if (token === "*") next[0] = previous[0]!;
      for (let index = 1; index <= name.length; index++) {
        const byte = name[index - 1]!;
        if (token === "*") next[index] = previous[index]! || next[index - 1]!;
        else if (previous[index - 1]) {
          if (typeof token === "object") {
            budget.step(token.ranges.length);
            const contained = token.ranges.some(([start, end]) => byte >= start && byte <= end);
            next[index] = Number(contained !== token.negate);
          } else next[index] = Number(token === "?" || token === byte);
        }
      }
      previous = next;
    }
    if (previous[name.length]) return true;
  }
  return false;
}

import type { FileSystem } from "./filesystem.js";
import type { ByteSink, ByteSource } from "./io.js";

export interface CommandInvokeOptions {
  readonly stdin?: ByteSource;
  readonly stdinIsDefault?: boolean;
  readonly stdout?: ByteSink;
  readonly stderr?: ByteSink;
  readonly cwd?: string;
  readonly env?: Readonly<Record<string, string>>;
  readonly replaceEnv?: boolean;
}

export type CommandInvoker = (
  command: string,
  args: readonly string[],
  options?: CommandInvokeOptions,
) => Promise<CommandResult>;

export type InvocationCleanup = () => void | Promise<void>;

export interface CommandContext {
  readonly command: string;
  readonly args: readonly string[];
  readonly stdin: ByteSource;
  readonly stdinIsDefault?: boolean;
  readonly stdout: ByteSink;
  readonly stderr: ByteSink;
  cwd: string;
  env: Record<string, string>;
  readonly fs: FileSystem;
  readonly signal: AbortSignal;
  readonly invoke?: CommandInvoker;
  readonly registerCleanup?: (cleanup: InvocationCleanup) => void;
}

export interface CommandResult {
  readonly exitCode: number;
}

export type CommandHandler = (
  context: CommandContext,
) => CommandResult | Promise<CommandResult>;

export type AsyncCommandHandler = (context: CommandContext) => Promise<CommandResult>;

export interface CommandDefinition {
  readonly name: string;
  readonly description?: string;
  readonly execute: CommandHandler;
}

export interface RegisterCommandOptions {
  readonly replace?: boolean;
}

export class CommandRegistry {
  readonly #commands = new Map<string, CommandDefinition>();

  constructor(commands: Iterable<CommandDefinition> = []) {
    for (const command of commands) this.register(command);
  }

  register(command: CommandDefinition, options: RegisterCommandOptions = {}): this {
    const { name, execute } = command;
    if (typeof name !== "string" || !name || /[\s/\0]/u.test(name)) {
      throw new TypeError("Command names must be nonempty and contain no whitespace, slash, or NUL");
    }
    if (typeof execute !== "function") {
      throw new TypeError("Command execute must be a function");
    }
    if (this.#commands.has(name) && !options.replace) {
      throw new Error(`Command already registered: ${name}`);
    }
    this.#commands.set(name, Object.freeze({ ...command, name, execute }));
    return this;
  }

  get(name: string): CommandDefinition | undefined {
    return this.#commands.get(name);
  }

  has(name: string): boolean {
    return this.#commands.has(name);
  }

  unregister(name: string): boolean {
    return this.#commands.delete(name);
  }

  list(): readonly CommandDefinition[] {
    return Array.from(this.#commands.values());
  }
}

export function validateExitCode(exitCode: number): number {
  if (!Number.isInteger(exitCode) || exitCode < 0 || exitCode > 255) {
    throw new RangeError("Exit status must be an integer between 0 and 255");
  }
  return exitCode;
}

import { getSystemErrorMap } from "node:util";

const systemErrnos = new Map([...getSystemErrorMap()].map(([errno, [name]]) => [name, errno]));

const descriptions = {
  EACCES: "permission denied",
  EAGAIN: "resource temporarily unavailable",
  EBADF: "bad file descriptor",
  EBUSY: "resource busy or locked",
  ECANCELED: "operation canceled",
  EEXIST: "file already exists",
  EFBIG: "file too large",
  EINTR: "interrupted system call",
  EINVAL: "invalid argument",
  EIO: "input/output error",
  EISDIR: "illegal operation on a directory",
  ELOOP: "too many symbolic links encountered",
  EMFILE: "too many open files",
  ENAMETOOLONG: "name too long",
  ENFILE: "file table overflow",
  ENOENT: "no such file or directory",
  ENOMEM: "not enough memory",
  ENOSPC: "no space left on device",
  ENOSYS: "function not implemented",
  ENOTDIR: "not a directory",
  ENOTEMPTY: "directory not empty",
  ENOTSUP: "operation not supported",
  EOPNOTSUPP: "operation not supported",
  EPERM: "operation not permitted",
  EPIPE: "broken pipe",
  EROFS: "read-only file system",
  ETIMEDOUT: "operation timed out",
  EXDEV: "cross-device link not permitted",
} as const;

export type ErrnoCode = keyof typeof descriptions;

export interface FsErrorOptions extends ErrorOptions {
  readonly syscall?: string;
  readonly path?: string;
  readonly dest?: string;
  readonly message?: string;
}

export class FsError extends Error {
  readonly code: ErrnoCode;
  readonly errno: number;
  readonly syscall?: string;
  readonly path?: string;
  readonly dest?: string;

  constructor(code: ErrnoCode, options: FsErrorOptions = {}) {
    if (!isErrnoCode(code)) throw new TypeError(`Unsupported errno code: ${String(code)}`);
    const errno = systemErrnos.get(code === "EOPNOTSUPP" ? "ENOTSUP" : code);
    if (errno === undefined) throw new TypeError(`Unsupported platform errno code: ${code}`);
    const operation = options.syscall ? `, ${options.syscall}` : "";
    const path = options.path === undefined ? "" : ` '${options.path}'`;
    const destination = options.dest === undefined ? "" : ` -> '${options.dest}'`;
    super(`${code}: ${options.message ?? descriptions[code]}${operation}${path}${destination}`, options);
    this.name = "FsError";
    this.code = code;
    this.errno = errno;
    if (options.syscall !== undefined) this.syscall = options.syscall;
    if (options.path !== undefined) this.path = options.path;
    if (options.dest !== undefined) this.dest = options.dest;
  }
}

export function isErrnoCode(code: unknown): code is ErrnoCode {
  return typeof code === "string" && Object.hasOwn(descriptions, code);
}

export function isFsError(error: unknown, code?: ErrnoCode): error is FsError {
  return error instanceof FsError && (code === undefined || error.code === code);
}

export function toFsError(error: unknown, options: FsErrorOptions = {}): FsError {
  if (error instanceof FsError && Object.keys(options).length === 0) return error;
  const source = typeof error === "object" && error !== null
    ? error as Record<string, unknown>
    : {};
  const details: FsErrorOptions = {
    ...(typeof source.syscall === "string" ? { syscall: source.syscall } : {}),
    ...(typeof source.path === "string" ? { path: source.path } : {}),
    ...(typeof source.dest === "string" ? { dest: source.dest } : {}),
    cause: error,
    ...options,
  };
  return new FsError(isErrnoCode(source.code) ? source.code : "EIO", details);
}

