import { TransformStream } from "node:stream/web";
import { FsError } from "./errors.js";

export type ByteSource = AsyncIterable<Uint8Array>;

export interface ByteSink {
  write(chunk: Uint8Array): Promise<void>;
}

export interface BytePipe {
  readonly readable: ByteSource;
  readonly writable: ByteSink;
  close(): Promise<void>;
  abort(reason?: unknown): Promise<void>;
}

export interface BytePipeOptions {
  readonly highWaterMark?: number;
  readonly signal?: AbortSignal;
}

export interface CollectOptions {
  readonly maxBytes: number;
  readonly signal?: AbortSignal;
}

export function createBytePipe(options: BytePipeOptions = {}): BytePipe {
  const highWaterMark = options.highWaterMark ?? 64 * 1024;
  const signal = options.signal;
  if (!Number.isSafeInteger(highWaterMark) || highWaterMark < 1) {
    throw new RangeError("highWaterMark must be a positive safe integer");
  }
  const stream = new TransformStream<Uint8Array, Uint8Array>(
    undefined,
    { highWaterMark: 1 },
    { highWaterMark, size: (chunk) => chunk.byteLength },
  );
  const reader = stream.readable.getReader();
  const writer = stream.writable.getWriter();
  let ended = false;
  let failed = false;
  let failure: unknown;
  let closePromise: Promise<void> | undefined;
  let abortPromise: Promise<void> | undefined;
  let finished = false;
  const abort = (reason: unknown = new FsError("EPIPE", { syscall: "pipe" })): Promise<void> => {
    if (abortPromise) return abortPromise;
    if (finished) return Promise.resolve();
    failed = true;
    failure = reason;
    ended = true;
    abortPromise = Promise.allSettled([reader.cancel(reason), writer.abort(reason)]).then(() => {});
    return abortPromise;
  };
  const onAbort = (): void => { void abort(signal?.reason); };
  const cleanup = (): void => signal?.removeEventListener("abort", onAbort);
  void writer.closed.catch(() => {});
  void reader.closed.then(cleanup, cleanup);
  if (signal?.aborted) onAbort();
  else signal?.addEventListener("abort", onAbort, { once: true });
  const iterator = (async function* (): AsyncGenerator<Uint8Array> {
    try {
      while (true) {
        if (failed) throw failure;
        const result = await reader.read();
        if (failed) throw failure;
        if (result.done) {
          finished = true;
          return;
        }
        yield result.value;
      }
    } finally {
      if (!finished) await abort();
      reader.releaseLock();
    }
  })();
  const readable: AsyncIterableIterator<Uint8Array> = {
    [Symbol.asyncIterator]() { return this; },
    next() { return iterator.next(); },
    async return() {
      if (!finished) await abort();
      try {
        return await iterator.return(undefined);
      } finally {
        reader.releaseLock();
      }
    },
    async throw(reason) {
      await abort(reason);
      try {
        return await iterator.throw(reason);
      } finally {
        reader.releaseLock();
      }
    },
  };
  return {
    readable,
    writable: {
      async write(chunk) {
        if (failed) throw failure;
        if (ended) throw new FsError("EPIPE", { syscall: "write" });
        if (!(chunk instanceof Uint8Array)) throw new TypeError("Byte sinks require Uint8Array chunks");
        if (chunk.byteLength > 0) await writer.write(new Uint8Array(chunk));
      },
    },
    close() {
      if (failed) return Promise.reject(failure);
      ended = true;
      closePromise ??= writer.close();
      return closePromise;
    },
    abort,
  };
}

export function toByteSource(input: string | Uint8Array): ByteSource {
  if (typeof input !== "string" && !(input instanceof Uint8Array)) {
    throw new TypeError("Byte source input must be a string or Uint8Array");
  }
  const bytes = typeof input === "string" ? new TextEncoder().encode(input) : new Uint8Array(input);
  return (async function* () {
    if (bytes.byteLength > 0) yield bytes;
  })();
}

export async function writeText(sink: ByteSink, text: string): Promise<void> {
  await sink.write(new TextEncoder().encode(text));
}

export async function writeBytes(sink: ByteSink, chunk: Uint8Array, signal?: AbortSignal): Promise<void> {
  if (!(chunk instanceof Uint8Array)) throw new TypeError("Byte sinks require Uint8Array chunks");
  await abortable(() => sink.write(chunk), signal);
}

export async function pipeBytes(source: ByteSource, sink: ByteSink, signal?: AbortSignal): Promise<void> {
  signal?.throwIfAborted();
  for await (const chunk of readBytes(source, signal)) {
    await writeBytes(sink, chunk, signal);
  }
  signal?.throwIfAborted();
}

export async function collectBytes(source: ByteSource, options: CollectOptions): Promise<Uint8Array> {
  if (!Number.isSafeInteger(options.maxBytes) || options.maxBytes < 0) {
    throw new RangeError("maxBytes must be a nonnegative safe integer");
  }
  const chunks: Uint8Array[] = [];
  let size = 0;
  options.signal?.throwIfAborted();
  for await (const chunk of readBytes(source, options.signal)) {
    if (chunk.byteLength > options.maxBytes - size) {
      throw new FsError("EFBIG", { syscall: "collectBytes", message: "output exceeds maxBytes" });
    }
    if (chunk.byteLength > 0) chunks.push(new Uint8Array(chunk));
    size += chunk.byteLength;
  }
  options.signal?.throwIfAborted();
  const result = new Uint8Array(size);
  let offset = 0;
  for (const chunk of chunks) {
    result.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return result;
}

export async function collectText(source: ByteSource, options: CollectOptions): Promise<string> {
  return new TextDecoder().decode(await collectBytes(source, options));
}

async function abortable<Result>(operation: () => PromiseLike<Result>, signal?: AbortSignal): Promise<Result> {
  signal?.throwIfAborted();
  if (!signal) return operation();
  return new Promise<Result>((resolve, reject) => {
    const onAbort = (): void => {
      signal.removeEventListener("abort", onAbort);
      reject(signal.reason);
    };
    signal.addEventListener("abort", onAbort, { once: true });
    try {
      Promise.resolve(operation()).then(
        (result) => {
          signal.removeEventListener("abort", onAbort);
          resolve(result);
        },
        (error: unknown) => {
          signal.removeEventListener("abort", onAbort);
          reject(error);
        },
      );
    } catch (error) {
      signal.removeEventListener("abort", onAbort);
      reject(error);
    }
  });
}

export async function* readBytes(source: ByteSource, signal?: AbortSignal): AsyncGenerator<Uint8Array> {
  signal?.throwIfAborted();
  const iterator = source[Symbol.asyncIterator]();
  let finished = false;
  let failed = false;
  try {
    while (true) {
      const result = await abortable(() => iterator.next(), signal);
      if (result.done) {
        finished = true;
        return;
      }
      if (!(result.value instanceof Uint8Array)) throw new TypeError("Byte sources must yield Uint8Array chunks");
      yield result.value;
    }
  } catch (error) {
    failed = true;
    throw error;
  } finally {
    if (!finished && iterator.return) {
      const cleanup = Promise.resolve().then(() => iterator.return!());
      if (signal?.aborted) void cleanup.catch(() => {});
      else {
        try { await abortable(() => cleanup, signal); }
        catch (error) { if (!failed) throw error; }
      }
    }
  }
}

import { posix } from "node:path";
import { FsError } from "./errors.js";

export const posixPath = posix;
export const basename = posix.basename;
export const dirname = posix.dirname;
export const extname = posix.extname;
export const joinPath = posix.join;
export const isAbsolutePath = posix.isAbsolute;

export function validatePath(path: string): void {
  if (typeof path !== "string" || path.includes("\0")) {
    throw new FsError("EINVAL", { syscall: "resolve", message: "paths must be strings without NUL bytes" });
  }
}

export function resolvePath(cwd: string, ...paths: string[]): string {
  validatePath(cwd);
  if (!posix.isAbsolute(cwd)) {
    throw new FsError("EINVAL", { syscall: "resolve", path: cwd, message: "cwd must be absolute" });
  }
  for (const path of paths) validatePath(path);
  return posix.resolve(cwd, ...paths);
}

export function normalizePath(path: string, cwd = "/"): string {
  return resolvePath(cwd, path);
}

export function relativePath(from: string, to: string): string {
  return posix.relative(normalizePath(from), normalizePath(to));
}

export function isPathWithin(root: string, path: string): boolean {
  const normalizedRoot = normalizePath(root);
  const normalizedPath = normalizePath(path);
  return normalizedRoot === "/"
    || normalizedPath === normalizedRoot
    || normalizedPath.startsWith(`${normalizedRoot}/`);
}

export function assertPathWithin(root: string, path: string): string {
  const normalizedPath = normalizePath(path);
  if (!isPathWithin(root, normalizedPath)) {
    throw new FsError("EACCES", { syscall: "resolve", path, message: "path escapes the allowed root" });
  }
  return normalizedPath;
}

import type { AsyncCommandHandler, CommandContext, CommandHandler, CommandRegistry, CommandResult } from "./command.js";
import type { FileSystemFactory } from "./filesystem.js";

export type Next = () => Promise<CommandResult>;

export type Middleware = (
  context: CommandContext,
  next: Next,
) => CommandResult | Promise<CommandResult>;

export interface PluginHost {
  readonly commands: CommandRegistry;
  use(middleware: Middleware): void;
  registerFileSystem(scheme: string, factory: FileSystemFactory): void;
}

export interface VirtualShellPlugin {
  readonly name: string;
  setup(host: PluginHost): void | Promise<void>;
  dispose?(): void | Promise<void>;
}

export function composeMiddleware(
  middleware: readonly Middleware[],
  terminal: CommandHandler,
): AsyncCommandHandler {
  const stack = [...middleware];
  if (typeof terminal !== "function" || stack.some((handler) => typeof handler !== "function")) {
    throw new TypeError("Middleware and terminal handlers must be functions");
  }
  return async (context) => {
    let lastIndex = -1;
    const dispatch = async (index: number): Promise<CommandResult> => {
      if (index <= lastIndex) throw new Error("next() may only be called once per middleware");
      lastIndex = index;
      context.signal.throwIfAborted();
      const handler = stack[index];
      if (!handler) return terminal(context);
      let active = true;
      let downstream: Promise<CommandResult> | undefined;
      let downstreamPending = false;
      const next: Next = () => {
        const result = active
          ? dispatch(index + 1)
          : Promise.reject<CommandResult>(new Error("next() cannot be called after middleware completed"));
        if (active && !downstream) {
          downstream = result;
          downstreamPending = true;
          void result.then(
            () => { downstreamPending = false; },
            () => { downstreamPending = false; },
          );
        } else void result.catch(() => {});
        return result;
      };
      try {
        const result = await handler(context, next);
        if (downstreamPending) throw new Error("Middleware must await or return next()");
        return result;
      } finally {
        active = false;
        if (downstream) await downstream.then(() => {}, () => {});
      }
    };
    return dispatch(0);
  };
}

export { Shell } from "./shell.js";
export { parseShell } from "./parser.js";
export { ShellLimitError, ShellSyntaxError } from "./types.js";
export type { ShellCommandContext, ShellExecOptions, ShellInvokeOptions, ShellLimits, ShellOptions, ShellResult } from "./types.js";

import { CommandRegistry, resolvePath, toByteSource, writeText } from "../contracts/index.js";
import type {
  ByteSink, CommandDefinition, FileSystemFactory, Middleware, PluginHost,
  RegisterCommandOptions, VirtualShellPlugin,
} from "../contracts/index.js";
import { parseShellUnit } from "./parser.js";
import { ShellInput } from "./input.js";
import { byteLocale } from "./locale.js";
import { Budget, Capture, interruptible, resolveLimits, Runtime } from "./runtime.js";
import type { State } from "./runtime.js";
import { ShellLimitError, ShellSyntaxError } from "./types.js";
import type { ShellExecOptions, ShellOptions, ShellResult } from "./types.js";
import { InvocationScope, invocationScope, throwCleanupFailures } from "./cleanup.js";

export class Shell implements PluginHost {
  readonly commands: CommandRegistry;
  readonly #middleware: Middleware[] = [];
  readonly #filesystems = new Map<string, FileSystemFactory>();
  readonly #plugins: VirtualShellPlugin[] = [];
  readonly #options: ShellOptions;
  #ready: Promise<void> = Promise.resolve();
  #disposed = false;
  #disposal: Promise<void> | undefined;
  readonly #active = new Set<{ scope: InvocationScope; budget: Budget }>();

  constructor(options: ShellOptions) {
    if (!options?.fs) throw new TypeError("Shell requires an explicit filesystem");
    resolveLimits(options.limits);
    this.#options = { ...options, cwd: resolvePath("/", options.cwd ?? "/"), env: { ...options.env }, limits: { ...options.limits } };
    this.commands = options.commands ?? new CommandRegistry();
  }

  use(middleware: Middleware | VirtualShellPlugin): this {
    if (this.#disposed) throw new Error("Shell is disposed");
    if (typeof middleware === "function") this.#middleware.push(middleware);
    else {
      if (!middleware || typeof middleware.setup !== "function") throw new TypeError("Expected middleware or shell plugin");
      this.#ready = this.#ready.then(async () => {
        await middleware.setup(this);
        this.#plugins.push(middleware);
      });
      void this.#ready.catch(() => undefined);
    }
    return this;
  }

  register(command: CommandDefinition, options?: RegisterCommandOptions): this {
    if (this.#disposed) throw new Error("Shell is disposed");
    this.commands.register(command, options);
    return this;
  }

  registerFileSystem(scheme: string, factory: FileSystemFactory): void {
    if (this.#disposed) throw new Error("Shell is disposed");
    if (!/^[a-z][a-z0-9+.-]*$/u.test(scheme)) throw new TypeError("Invalid filesystem scheme");
    if (this.#filesystems.has(scheme)) throw new Error(`Filesystem already registered: ${scheme}`);
    this.#filesystems.set(scheme, factory);
  }

  async createFileSystem(scheme: string, options: Readonly<Record<string, unknown>> = {}): Promise<Awaited<ReturnType<FileSystemFactory>>> {
    if (this.#disposed) throw new Error("Shell is disposed");
    await this.#ready;
    const factory = this.#filesystems.get(scheme);
    if (!factory) throw new Error(`Unknown filesystem scheme: ${scheme}`);
    return factory(options);
  }

  async exec(source: string, options: ShellExecOptions = {}): Promise<ShellResult> {
    if (this.#disposed) throw new Error("Shell is disposed");
    const budget = new Budget(resolveLimits(this.#options.limits, options.limits), options.signal);
    const scope = new InvocationScope(options.signal);
    const active = { scope, budget };
    this.#active.add(active);
    let failed = false;
    let failure: unknown;
    let result: ShellResult | undefined;
    try { result = await this.#execute(source, options, scope, budget); }
    catch (error) { failed = true; failure = error; }
    finally {
      await scope.close();
      this.#active.delete(active);
    }
    options.signal?.throwIfAborted();
    if (failed) throw failure;
    throwCleanupFailures(scope.failures);
    return result!;
  }

  async #execute(source: string, options: ShellExecOptions, scope: InvocationScope, budget: Budget): Promise<ShellResult> {
    if (typeof source !== "string") throw new TypeError("Shell source must be a string");
    if (Buffer.byteLength(source) > budget.limits.maxSourceBytes) throw new ShellLimitError("maxSourceBytes");
    budget.source(Buffer.byteLength(source));
    budget.signal.throwIfAborted();
    const stdout = new Capture();
    const stderr = new Capture();
    const sink = (capture: Capture, external?: ByteSink): ByteSink => budget.sink({
      write: async (chunk) => {
        await capture.write(chunk);
        if (external) await external.write(chunk);
      },
    });
    let stdin: ShellInput | undefined;
    const io = {
      [invocationScope]: scope,
      stdin: toByteSource(""),
      stdinIsDefault: options.stdin === undefined,
      stdout: sink(stdout, options.stdout), stderr: sink(stderr, options.stderr),
    };
    let exitCode: number;
    let failed = false;
    try {
      try {
        let unit = parseShellUnit(source, 0, byteLocale({ ...this.#options.env, ...options.env }));
        stdin = new ShellInput(typeof options.stdin === "string" || options.stdin instanceof Uint8Array ? toByteSource(options.stdin) : options.stdin ?? toByteSource(""), budget);
        io.stdin = stdin;
        await interruptible(this.#ready, budget.signal);
        const cwd = resolvePath("/", options.cwd ?? this.#options.cwd ?? "/");
        const variables = Object.assign(Object.create(null) as Record<string, string>, this.#options.env, options.env, { PWD: cwd });
        for (const [name, value] of Object.entries(variables)) {
          if (name.includes("\0") || name.includes("=") || typeof value !== "string" || value.includes("\0")) throw new TypeError("Invalid environment entry");
        }
        const state: State = {
          cwd, variables, exported: new Set(Object.keys(variables)), functions: new Map(), positional: [],
          status: 0, substitutionStatus: 0, depth: 0, loopDepth: 0, functionDepth: 0, locals: [], pipefail: false, profile: "bash",
        };
        const runtime = new Runtime(options.fs ?? this.#options.fs, this.commands, [...this.#middleware], budget, AbortSignal.any([budget.signal, scope.signal]), undefined, undefined, budget.signal);
        exitCode = 0;
        while (true) {
          for (const warning of unit.script.warnings ?? []) await writeText(io.stderr, `shell: warning: ${warning}\n`);
          if (unit.script.lists.length) {
            const result = await interruptible(runtime.runUnit(unit.script, state, io), budget.signal);
            exitCode = result.exitCode;
            if (result.terminated) break;
          }
          if (unit.next >= source.length) break;
          budget.signal.throwIfAborted();
          unit = parseShellUnit(source, unit.next, byteLocale(state.variables));
        }
      } catch (error) {
        if (!(error instanceof ShellSyntaxError)) throw error;
        const line = source.slice(0, error.offset).split("\n").length;
        if (error.unclosedQuote) {
          await writeText(io.stderr, `shell: -c: line ${error.unclosedQuote.line}: unexpected EOF while looking for matching \`${error.unclosedQuote.quote}'\n`);
        } else if (error.exitCode === 127) {
          const token = /^[;&|()<>]|^[^\s;&|()<>]+/u.exec(source.slice(error.offset))?.[0] ?? "newline";
          await writeText(io.stderr, `shell: -c: line ${line}: syntax error near unexpected token \`${token}'\nshell: -c: line ${line}: \`${source.split("\n")[line - 1] ?? ""}'\n`);
        } else if (error.offset >= source.length && !/Unterminated|nesting|Unsupported/u.test(error.reason)) {
          const context = error.incompleteCommand ? ` from \`${error.incompleteCommand.name}' command on line ${error.incompleteCommand.line}` : "";
          await writeText(io.stderr, `shell: -c: line ${source.split("\n").length + Number(!source.endsWith("\n"))}: syntax error: unexpected end of file${context}\n`);
        } else await writeText(io.stderr, `shell: ${error.message}\n`);
        exitCode = error.exitCode;
      }
    } catch (error) { failed = true; throw error; }
    finally {
      try { await stdin?.close(); }
      catch (error) { if (!failed) throw error; }
    }
    const stdoutBytes = stdout.bytes();
    const stderrBytes = stderr.bytes();
    return {
      stdout: new TextDecoder("utf-8", { ignoreBOM: true }).decode(stdoutBytes),
      stderr: new TextDecoder("utf-8", { ignoreBOM: true }).decode(stderrBytes),
      stdoutBytes, stderrBytes, exitCode,
    };
  }

  dispose(): Promise<void> {
    if (this.#disposal) return this.#disposal;
    this.#disposed = true;
    const active = [...this.#active];
    const drains: Promise<void>[] = [];
    this.#disposal = Promise.resolve().then(() => this.#dispose(active, drains));
    for (const { scope, budget } of active) {
      const drain = scope.close();
      budget.controller.abort(new Error("Shell is disposed"));
      drains.push(drain);
    }
    return this.#disposal;
  }

  async #dispose(active: readonly { scope: InvocationScope }[], drains: readonly Promise<void>[]): Promise<void> {
    await Promise.all(drains);
    await this.#ready.catch(() => undefined);
    const failures: unknown[] = [];
    for (const plugin of [...this.#plugins].reverse()) {
      try { await plugin.dispose?.(); } catch (error) { failures.push(error); }
    }
    const cleanupFailures = active.flatMap(({ scope }) => scope.failures);
    if (failures.length) throw new AggregateError([...cleanupFailures, ...failures], "Plugin disposal failed");
    throwCleanupFailures(cleanupFailures);
  }
}

import type { ByteSink, ByteSource, CommandContext, CommandRegistry, CommandResult, FileSystem } from "../contracts/index.js";

export interface ShellInvokeOptions {
  readonly stdin?: ByteSource;
  readonly stdinIsDefault?: boolean;
  readonly stdout?: ByteSink;
  readonly stderr?: ByteSink;
  readonly cwd?: string;
  readonly env?: Readonly<Record<string, string>>;
  readonly replaceEnv?: boolean;
}

export interface ShellCommandContext extends CommandContext {
  readonly invoke: (command: string, args: readonly string[], options?: ShellInvokeOptions) => Promise<CommandResult>;
}

export interface ShellLimits {
  readonly maxOutputBytes?: number;
  readonly maxCommands?: number;
  readonly maxLoopIterations?: number;
  readonly maxSubstitutionDepth?: number;
  readonly maxSourceBytes?: number;
  readonly maxExpansionFields?: number;
  readonly maxExpansionBytes?: number;
  readonly pipeHighWaterMark?: number;
}

export interface ShellOptions {
  readonly fs: FileSystem;
  readonly commands?: CommandRegistry;
  readonly cwd?: string;
  readonly env?: Readonly<Record<string, string>>;
  readonly limits?: ShellLimits;
}

export interface ShellExecOptions {
  readonly fs?: FileSystem;
  readonly cwd?: string;
  readonly env?: Readonly<Record<string, string>>;
  readonly stdin?: string | Uint8Array | ByteSource;
  readonly stdout?: ByteSink;
  readonly stderr?: ByteSink;
  readonly signal?: AbortSignal;
  readonly limits?: ShellLimits;
}

export interface ShellResult {
  readonly stdout: string;
  readonly stderr: string;
  readonly stdoutBytes: Uint8Array;
  readonly stderrBytes: Uint8Array;
  readonly exitCode: number;
}

export class ShellSyntaxError extends SyntaxError {
  constructor(readonly reason: string, readonly offset: number, readonly exitCode = 2, readonly incompleteCommand?: { name: string; line: number }, readonly unclosedQuote?: { quote: string; line: number }) {
    super(`${reason} at offset ${offset}`);
    this.name = "ShellSyntaxError";
  }
}

export class ShellLimitError extends Error {
  constructor(readonly limit: keyof ShellLimits) {
    super(`Shell limit exceeded: ${limit}`);
    this.name = "ShellLimitError";
  }
}

import { ShellSyntaxError } from "./types.js";
import { arithmeticEnd, prepareArithmetic } from "./arithmetic.js";
import type { ArithmeticProgram } from "./arithmetic.js";

export type WordPart =
  | { kind: "text"; value: string; quoted: boolean }
  | { kind: "arithmetic"; expression: ArithmeticProgram; source: string; line: number; quoted: boolean }
  | { kind: "variable"; name: string; quoted: boolean; line?: number; length?: boolean; operator?: string; alternate?: Word; replacement?: Word; substring?: { offset: Word; length?: Word; source: string } }
  | { kind: "failed-substitution"; diagnostic: string; quoted: boolean }
  | { kind: "substitution"; script: Script; line: number; sourceLine?: number; quoted: boolean };

export interface Word {
  readonly parts: WordPart[];
  readonly offset: number;
  readonly plain?: string;
  readonly spelling?: string;
  readonly printedNewlines?: number;
}

interface Token {
  kind: "word" | "operator" | "end";
  value: string;
  offset: number;
  end: number;
  word?: Word;
  document?: HereDocument;
}

export interface HereDocument {
  readonly delimiter: string;
  readonly quoted: boolean;
  readonly stripTabs: boolean;
  readonly offset: number;
  readonly depth: number;
  body: string;
  endLine: number;
}

export class HereDocumentSyntaxError extends Error {
  constructor(readonly diagnostic: string) { super(diagnostic); }
}

export interface Redirect {
  readonly descriptor: number;
  readonly operator: string;
  readonly target: Word;
  readonly move?: boolean;
  readonly document?: HereDocument;
  readonly line?: number;
}

export interface CaseClause {
  readonly patterns: Word[];
  readonly body: Script;
  readonly terminator: ";;" | ";&" | ";;&" | "esac";
}

export type Command = (
  | { kind: "simple"; words: Word[] }
  | { kind: "subshell"; body: Script }
  | { kind: "group"; body: Script }
  | { kind: "if"; branches: { condition: Script; body: Script }[]; otherwise?: Script }
  | { kind: "case"; subject: Word; clauses: CaseClause[] }
  | { kind: "while"; condition: Script; body: Script }
  | { kind: "until"; condition: Script; body: Script }
  | { kind: "for"; name: string; words?: Word[]; body: Script }
  | { kind: "function"; name: string; body: Command }
  | { kind: "arithmetic"; expression: ArithmeticProgram; source: string }
) & { redirects: Redirect[]; line?: number; sourceName?: string };

export interface Pipeline {
  readonly commands: Command[];
  readonly negate: boolean;
}

export interface AndOr {
  readonly pipelines: Pipeline[];
  readonly operators: ("&&" | "||")[];
}

export interface Script {
  readonly lists: AndOr[];
  readonly warnings?: readonly string[];
  readonly line?: number;
  readonly printedLines?: ReadonlyMap<Command, number>;
  readonly printedNewlines?: number;
}

function printedSimpleLines(lists: readonly AndOr[], separators: readonly boolean[]): Pick<Script, "printedLines" | "printedNewlines"> {
  const printedLines = new Map<Command, number>();
  let line = 1;
  for (let index = 0; index < lists.length; index++) {
    for (const pipeline of lists[index]!.pipelines) for (const command of pipeline.commands) {
      if (command.kind !== "simple" || !command.words.length || command.redirects.some(redirect => redirect.document)) return {};
      const words = [...command.words, ...command.redirects.map(redirect => redirect.target)];
      if (words.some(word => word.printedNewlines === undefined)) return {};
      printedLines.set(command, line + command.words[0]!.printedNewlines!);
      for (const word of words) line += word.printedNewlines!;
    }
    if (index < lists.length - 1 && separators[index]) line++;
  }
  return { printedLines, printedNewlines: line - 1 };
}

class IncompleteShellInput extends Error {}

class Lexer {
  position = 0;
  printedNewlineReduction = 0;
  unprintedWords = 0;
  delimiterOperator: string | undefined;
  readonly documents: HereDocument[] = [];

  constructor(readonly source: string, readonly depth: number, readonly warnings: string[] = [], readonly lineOffset = 0, readonly byteLocale = false, readonly documentLine?: number, readonly partial = false) {
    if (depth > 64) throw new ShellSyntaxError("Syntax nesting exceeds 64", 0);
  }

  lineAt(position: number): number { return this.lineOffset + this.source.slice(0, position).split("\n").length; }

  error(message: string, unclosedQuote?: { quote: string; line: number }): never {
    throw new ShellSyntaxError(message, this.position, 2, undefined, unclosedQuote);
  }

  next(): Token {
    while (this.position < this.source.length) {
      const current = this.source[this.position]!;
      if (current === " " || current === "\t") {
        this.position++;
      } else if (current === "\\" && this.source[this.position + 1] === "\n") {
        this.position += 2;
      } else if (current === "#") {
        while (this.position < this.source.length && this.source[this.position] !== "\n") this.position++;
      } else break;
    }
    const offset = this.position;
    if (offset === this.source.length) {
      if (this.partial) throw new IncompleteShellInput();
      this.readDocuments();
      return { kind: "end", value: "", offset, end: offset };
    }
    let logical = "";
    let cursor = offset;
    const ends: number[] = [];
    while (cursor < this.source.length && logical.length < 3) {
      if (this.source.startsWith("\\\n", cursor)) { cursor += 2; continue; }
      logical += this.source[cursor++]!;
      ends.push(cursor);
    }
    const operator = /^(?:;;&|<<<|<<-|;&|&&|\|\||>>|>&|<&|>\||<<|;;|&>|[;\n|&()<>])/u.exec(logical)?.[0];
    if (operator) {
      if (["&", "&>"].includes(operator)) this.error(`Unsupported operator ${operator}`);
      this.position = ends[operator.length - 1]!;
      if (operator === "<<" || operator === "<<-") this.delimiterOperator = operator;
      if (operator === "\n") this.readDocuments();
      return { kind: "operator", value: operator, offset, end: this.position };
    }
    const delimiterOperator = this.delimiterOperator;
    this.delimiterOperator = undefined;
    const word = this.word(undefined, false, delimiterOperator !== undefined);
    if (this.position <= offset) this.error("Tokenizer made no progress");
    let document: HereDocument | undefined;
    if (delimiterOperator) {
      document = {
        delimiter: word.parts.map((part) => part.kind === "text" ? part.value : "").join(""),
        quoted: word.parts.some((part) => part.quoted), stripTabs: delimiterOperator === "<<-", offset,
        body: "", endLine: this.lineAt(offset), depth: this.depth,
      };
      this.documents.push(document);
    }
    return { kind: "word", value: word.plain ?? "", offset, end: this.position, word: { ...word, spelling: this.source.slice(offset, this.position) }, ...(document ? { document } : {}) };
  }

  readDocuments(): void {
    for (const document of this.documents.splice(0)) {
      let body = "";
      let terminated = false;
      while (this.position < this.source.length) {
        let line = "";
        while (this.position < this.source.length) {
          const current = this.source[this.position++]!;
          if (!document.quoted && current === "\\" && this.position < this.source.length) {
            const next = this.source[this.position++]!;
            if (next !== "\n") line += current + next;
          } else if (current === "\n") break;
          else line += current;
        }
        if (line === document.delimiter || (document.stripTabs && line.replace(/^\t+/u, "") === document.delimiter)) {
          terminated = true;
          break;
        }
        body += (document.stripTabs ? line.replace(/^\t+/u, "") : line) + "\n";
      }
      if (!terminated && this.partial) throw new IncompleteShellInput();
      if (!terminated) this.warnings.push(`here-document at offset ${document.offset} delimited by end-of-file (wanted ${JSON.stringify(document.delimiter)})`);
      document.body = body;
      document.endLine = this.lineAt(Math.max(0, this.position - 1));
    }
  }

  *documentWords(): Generator<Word> {
    let text = "";
    while (this.position < this.source.length) {
      const current = this.source[this.position]!;
      if (current === "$" || current === "`") {
        if (text) { yield { offset: 0, parts: [{ kind: "text", value: text, quoted: true }] }; text = ""; }
        const offset = this.position;
        const parts: WordPart[] = [];
        try { this.expansion(parts, true); }
        catch (error) {
          if (!(error instanceof ShellSyntaxError) || /nesting|exceeds/u.test(error.reason)) throw error;
          if (this.source.startsWith("${", offset)) throw new HereDocumentSyntaxError(`shell: line ${this.documentLine}: ${this.source}: bad substitution\n`);
          if (current === "`") throw new HereDocumentSyntaxError(`shell: line ${this.documentLine}: bad substitution: no closing "\`" in ${this.source.slice(offset)}\n`);
          if (this.source.startsWith("$((", offset) && error.reason === "Unterminated arithmetic expression") throw new HereDocumentSyntaxError(`shell: line ${this.documentLine}: bad substitution: no closing \`)' in ${this.source}\n`);
          throw new HereDocumentSyntaxError(`shell: line ${this.documentLine}: ${error.message}\n`);
        }
        yield { offset, parts };
      } else if (current === "\\" && /[$`\\]/u.test(this.source[this.position + 1] ?? "")) {
        text += this.source[this.position + 1]!;
        this.position += 2;
      } else {
        text += current;
        this.position++;
      }
      if (text.length >= 1024) { yield { offset: 0, parts: [{ kind: "text", value: text, quoted: true }] }; text = ""; }
    }
    if (text) yield { offset: 0, parts: [{ kind: "text", value: text, quoted: true }] };
  }

  documentSubstitutionError(source: string, error: ShellSyntaxError, backtick = false): HereDocumentSyntaxError {
    const line = this.documentLine! + source.slice(0, error.offset).split("\n").length;
    if (error.offset >= source.length) {
      return new HereDocumentSyntaxError(backtick
        ? `shell: command substitution: line ${line}: syntax error: unexpected end of file\n`
        : `shell: command substitution: line ${line}: unexpected EOF while looking for matching \`)'\n`);
    }
    const token = /^[;&|()<>]|^[^\s;&|()<>]+/u.exec(source.slice(error.offset))?.[0] ?? "newline";
    const sourceLine = source.split("\n")[source.slice(0, error.offset).split("\n").length - 1] ?? "";
    return new HereDocumentSyntaxError(`shell: command substitution: line ${line}: syntax error near unexpected token \`${token}'\nshell: command substitution: line ${line}: \`${sourceLine}'\n`);
  }

  literalExpansion(): string {
    const backtick = this.source[this.position] === "`";
    const opening = this.source[this.position + 1];
    if (!backtick && opening !== "(" && opening !== "{") return this.source[this.position++]!;
    let value = backtick ? "`" : `$${opening}`;
    this.position += backtick ? 1 : 2;
    const closers = [backtick ? "`" : opening === "(" ? ")" : "}"];
    let quote = "";
    while (this.position < this.source.length) {
      const current = this.source[this.position++]!;
      if (current === "\\" && quote !== "'") {
        const next = this.source[this.position++];
        if (next === undefined) this.error("Trailing delimiter escape");
        if (next !== "\n") value += quote === '"' && !/[$`"\\]/u.test(next) ? current + next : next;
      } else if (quote) {
        if (current === quote) quote = "";
        else value += current;
      } else if (current === "'" || current === '"') quote = current;
      else {
        value += current;
        if (current === closers.at(-1)) {
          closers.pop();
          if (!closers.length) return value;
        } else if ((current === "(" && (closers.at(-1) === ")" || this.source[this.position - 2] === "$"))
          || (current === "{" && (closers.at(-1) === "}" || this.source[this.position - 2] === "$"))) {
          closers.push(current === "(" ? ")" : "}");
          if (closers.length + this.depth > 64) this.error("Syntax nesting exceeds 64");
        }
      }
    }
    this.error("Unterminated delimiter expansion syntax");
  }

  word(terminator?: string, enclosingQuoted = false, literal = false, arithmetic = false): Word {
    const offset = this.position;
    const reduction = this.printedNewlineReduction;
    const unprinted = this.unprintedWords;
    const parts: WordPart[] = [];
    let parentheses = 0;
    let conditionals = 0;
    let plain = true;
    const text = (value: string, quoted: boolean) => {
      const previous = parts.at(-1);
      if (previous?.kind === "text" && previous.quoted === quoted) previous.value += value;
      else parts.push({ kind: "text", value, quoted });
    };
    while (this.position < this.source.length) {
      const current = this.source[this.position]!;
      if (terminator ? terminator.includes(current) && (!arithmetic || current !== ":" || parentheses === 0 && conditionals === 0) : /[ \t\n;|&()<>]/u.test(current)) break;
      if (current === "$" && this.source[this.position + 1] === "'" && !enclosingQuoted && !literal) {
        plain = false;
        this.unprintedWords++;
        text(this.ansiWord(), true);
      } else if (current === "'" && !enclosingQuoted) {
        plain = false;
        const end = this.source.indexOf("'", this.position + 1);
        if (end === -1) this.error("Unterminated single quote", { quote: "'", line: this.lineAt(this.position) });
        text(this.source.slice(this.position + 1, end), true);
        this.position = end + 1;
      } else if (current === '"') {
        plain = false;
        const quoteLine = this.lineAt(this.position);
        this.position++;
        text("", true);
        while (this.position < this.source.length && this.source[this.position] !== '"') {
          const inner = this.source[this.position]!;
          if (!literal && (inner === "$" || inner === "`")) this.expansion(parts, true);
          else if (inner === "\\" && /[$`"\\\n]/u.test(this.source[this.position + 1] ?? "")) {
            const escaped = this.source[this.position + 1]!;
            if (escaped !== "\n") text(escaped, true);
            else this.printedNewlineReduction++;
            this.position += 2;
          } else {
            text(inner, true);
            this.position++;
          }
        }
        if (this.source[this.position] !== '"') this.error("Unterminated double quote", { quote: '"', line: quoteLine });
        this.position++;
      } else if (current === "\\") {
        if (this.source[this.position + 1] !== "\n") plain = false;
        this.position++;
        if (this.position === this.source.length) this.error("Trailing escape");
        if (this.source[this.position] !== "\n") text(this.source[this.position]!, true);
        else this.printedNewlineReduction++;
        this.position++;
      } else if (current === "$" || current === "`") {
        plain = false;
        if (literal) {
          if (current === "$" && ["'", '"'].includes(this.source[this.position + 1] ?? "")) this.error("Unsupported shell quoting in here-document delimiter");
          text(this.literalExpansion(), current === "`");
        }
        else this.expansion(parts, enclosingQuoted);
      } else {
        if (arithmetic) {
          if (current === "(") parentheses++;
          else if (current === ")") parentheses--;
          else if (current === "?") conditionals++;
          else if (current === ":" && conditionals > 0) conditionals--;
        }
        text(current, false);
        this.position++;
      }
    }
    const printedNewlines = this.source.slice(offset, this.position).split("\n").length - 1 - (this.printedNewlineReduction - reduction);
    return { parts, offset, ...(unprinted === this.unprintedWords ? { printedNewlines } : {}), ...(plain ? { plain: parts.map((part) => part.kind === "text" ? part.value : "").join("") } : {}) };
  }

  ansiWord(): string {
    const quoteLine = this.lineAt(this.position);
    this.position += 2;
    const bytes: number[] = [];
    const encoder = new TextEncoder();
    const escapes: Readonly<Record<string, number>> = { a: 7, b: 8, e: 27, E: 27, f: 12, n: 10, r: 13, t: 9, v: 11, "\\": 92, "'": 39, '"': 34, "?": 63 };
    while (this.position < this.source.length) {
      const character = String.fromCodePoint(this.source.codePointAt(this.position)!);
      this.position += character.length;
      if (character === "'") {
        const nul = bytes.indexOf(0);
        return new TextDecoder().decode(Uint8Array.from(nul < 0 ? bytes : bytes.slice(0, nul)));
      }
      if (character !== "\\") { bytes.push(...encoder.encode(character)); continue; }
      const escape = this.source[this.position++];
      if (escape === undefined) this.error("Unterminated ANSI-C quote", { quote: "'", line: quoteLine });
      if (escapes[escape] !== undefined) { bytes.push(escapes[escape]!); continue; }
      if (/[0-7]/u.test(escape)) {
        const digits = escape + (/^[0-7]{0,2}/u.exec(this.source.slice(this.position))?.[0] ?? "");
        this.position += digits.length - 1;
        bytes.push(parseInt(digits, 8) & 255);
      } else if (["x", "u", "U"].includes(escape)) {
        const maximum = escape === "x" ? 2 : escape === "u" ? 4 : 8;
        const digits = new RegExp(`^[0-9a-fA-F]{1,${maximum}}`, "u").exec(this.source.slice(this.position))?.[0];
        if (!digits) { bytes.push(92, escape.charCodeAt(0)); continue; }
        this.position += digits.length;
        const code = parseInt(digits, 16);
        if (escape === "x") bytes.push(code);
        else if (this.byteLocale && code > 127) {
          bytes.push(...encoder.encode(`\\${code <= 0xffff ? "u" : "U"}${code.toString(16).toUpperCase().padStart(code <= 0xffff ? 4 : 8, "0")}`));
        } else {
          if (code > 0x10ffff || (code >= 0xd800 && code <= 0xdfff)) this.error("Unsupported non-scalar ANSI-C Unicode escape");
          bytes.push(...encoder.encode(String.fromCodePoint(code)));
        }
      } else if (escape === "c" && this.source[this.position] !== "'" && this.position < this.source.length) {
        const control = this.source[this.position++]!;
        if (control === "\\" && this.source[this.position] === "\\") this.position++;
        bytes.push(control === "?" ? 127 : control.toUpperCase().charCodeAt(0) & 31);
      } else bytes.push(92, ...encoder.encode(escape));
    }
    this.error("Unterminated ANSI-C quote", { quote: "'", line: quoteLine });
  }

  expansion(parts: WordPart[], quoted: boolean): void {
    const line = this.documentLine ?? this.lineAt(this.position);
    if (this.source[this.position] === "`") {
      this.position++;
      let source = "";
      while (this.position < this.source.length && this.source[this.position] !== "`") {
        if (this.source[this.position] === "\\" && /[$`\\]/u.test(this.source[this.position + 1] ?? "")) this.position++;
        source += this.source[this.position++]!;
      }
      if (this.source[this.position] !== "`") this.error("Unterminated command substitution");
      this.position++;
      try { parts.push({ kind: "substitution", script: parseSource(source, this.depth + 1, this.warnings, line - 1, this.byteLocale), line, quoted }); }
      catch (error) {
        if (this.documentLine === undefined || !(error instanceof ShellSyntaxError) || /nesting|exceeds/u.test(error.reason)) throw error;
        parts.push({ kind: "failed-substitution", diagnostic: this.documentSubstitutionError(source, error, true).diagnostic, quoted });
      }
      return;
    }
    this.position++;
    if (["$", "!"].includes(this.source[this.position] ?? "") || (!quoted && ["'", '"'].includes(this.source[this.position] ?? ""))) this.error("Unsupported shell quoting or special parameter");
    if (this.source.startsWith("((", this.position)) {
      const start = this.position + 2;
      const end = arithmeticEnd(this.source, start);
      const source = this.source.slice(start, end);
      parts.push({ kind: "arithmetic", expression: prepareArithmetic(source), source, line, quoted });
      this.position = end + 2;
    } else if (this.source[this.position] === "(") {
      const start = this.position + 1;
      let nested: Parser;
      let script: Script;
      try {
        nested = new Parser(this.source.slice(start), this.depth + 1, this.warnings, this.lineAt(start) - 1, undefined, this.byteLocale);
        script = nested.script(new Set([")"]));
      }
      catch (error) {
        if (this.documentLine !== undefined && error instanceof ShellSyntaxError && !/nesting|exceeds/u.test(error.reason)) throw this.documentSubstitutionError(this.source.slice(start), error);
        if (error instanceof ShellSyntaxError && !/Unterminated|nesting|exceeds/u.test(error.reason)) throw new ShellSyntaxError(error.reason, start + error.offset, 127);
        throw error;
      }
      if (nested.current.value !== ")") {
        if (this.documentLine !== undefined) throw this.documentSubstitutionError(this.source.slice(start), new ShellSyntaxError("Unterminated command substitution", nested.current.offset));
        this.error("Unterminated command substitution");
      }
      if (nested.lexer.documents.length) this.error("Here-document requires a newline before closing command substitution");
      this.position += nested.current.end + 1;
      if (script.printedNewlines === undefined) this.unprintedWords++;
      else this.printedNewlineReduction += this.source.slice(start, this.position - 1).split("\n").length - 1 - script.printedNewlines;
      parts.push({ kind: "substitution", script, line, sourceLine: script.line ?? line, quoted });
    } else if (this.source[this.position] === "{") {
      this.position++;
      const parameterStart = this.position - 2;
      const length = this.source[this.position] === "#" && /[a-zA-Z_]/u.test(this.source[this.position + 1] ?? "");
      if (length) this.position++;
      const name = /^(?:[a-zA-Z_][a-zA-Z_0-9]*|[0-9]+|[?@*#-])/u.exec(this.source.slice(this.position))?.[0];
      if (!name) this.error("Unsupported parameter expansion");
      this.position += name.length;
      const operator = /^(?::[-=+?]|##|%%|\/\/|\/[#%]?|[-=+?#%])/u.exec(this.source.slice(this.position))?.[0];
      let alternate: Word | undefined;
      let replacement: Word | undefined;
      let substring: Extract<WordPart, { kind: "variable" }>["substring"];
      if (operator) {
        if (length) this.error("Invalid length expansion");
        this.position += operator.length;
        alternate = this.word(operator.startsWith("/") ? "/}" : "}", quoted && !["#", "##", "%", "%%"].includes(operator) && !operator.startsWith("/"));
        if (operator.startsWith("/") && this.source[this.position] === "/") {
          this.position++;
          replacement = this.word("}");
        }
      } else if (this.source[this.position] === ":") {
        if (length || !/^(?:[a-zA-Z_][a-zA-Z_0-9]*|[0-9]+)$/u.test(name)) this.error("Unsupported non-scalar substring expansion");
        this.position++;
        const offset = this.word(":}", true, false, true);
        let substringLength: Word | undefined;
        if (this.source[this.position] === ":") {
          this.position++;
          substringLength = this.word("}", true, false, true);
        }
        substring = { offset, ...(substringLength ? { length: substringLength } : {}), source: this.source.slice(parameterStart, this.position + 1) };
      }
      if (this.source[this.position] !== "}") this.error("Unterminated or unsupported parameter expansion");
      this.position++;
      parts.push({ kind: "variable", name, quoted, line, ...(length ? { length } : {}), ...(operator ? { operator, alternate: alternate! } : {}), ...(replacement ? { replacement } : {}), ...(substring ? { substring } : {}) });
    } else {
      const name = /^(?:[a-zA-Z_][a-zA-Z_0-9]*|[?@*#0-9-])/u.exec(this.source.slice(this.position))?.[0];
      if (name) {
        this.position += name.length;
        parts.push({ kind: "variable", name, quoted });
      } else parts.push({ kind: "text", value: "$", quoted });
    }
  }
}

class Parser {
  readonly lexer: Lexer;
  current: Token;
  lookahead: Token | undefined;
  nesting = 0;
  readonly openCommands: { name: string; line: number }[] = [];

  constructor(source: string, depth: number, warnings: string[] = [], lineOffset = 0, position?: number, byteLocale = false, partial = false) {
    if (position === undefined && depth === 0 && source.includes("\0")) throw new ShellSyntaxError("NUL bytes are not valid shell source", source.indexOf("\0"));
    this.lexer = new Lexer(source, depth, warnings, lineOffset, byteLocale, undefined, partial);
    this.lexer.position = position ?? 0;
    this.current = this.lexer.next();
  }

  error(message: string): never {
    const command = this.current.kind === "end" ? this.openCommands.findLast((command) => ["{", "if", "while", "until", "for", "case"].includes(command.name)) : undefined;
    throw new ShellSyntaxError(message, this.current.offset, 2, command);
  }

  advance(): Token {
    const previous = this.current;
    this.current = this.lookahead ?? this.lexer.next();
    this.lookahead = undefined;
    return previous;
  }

  peek(): Token {
    return this.lookahead ??= this.lexer.next();
  }

  is(value: string): boolean { return this.current.value === value; }

  isEnd(): boolean { return this.current.kind === "end"; }

  expect(value: string): void {
    if (!this.is(value)) this.error(`Expected ${value}`);
    this.advance();
  }

  newlines(): void { while (this.is("\n")) this.advance(); }

  script(stops = new Set<string>(), inputUnit = false): Script {
    const lists: AndOr[] = [];
    const separators: boolean[] = [];
    this.newlines();
    const line = this.lexer.lineAt(this.current.offset);
    while (this.current.kind !== "end" && !stops.has(this.current.value)) {
      const pipelines = [this.pipeline()];
      const operators: ("&&" | "||")[] = [];
      while (this.is("&&") || this.is("||")) {
        operators.push(this.advance().value as "&&" | "||");
        this.newlines();
        pipelines.push(this.pipeline());
      }
      lists.push({ pipelines, operators });
      separators.push(this.is("\n"));
      if (inputUnit && this.is("\n")) break;
      if (this.is(";") || this.is("\n")) {
        this.advance();
        if (inputUnit && this.is("\n")) break;
        this.newlines();
      } else if (!this.isEnd() && !this.is(")") && !(stops.has(this.current.value) && [";;", ";&", ";;&"].includes(this.current.value))) this.error("Expected command separator");
    }
    const printed = printedSimpleLines(lists, separators);
    return { lists, line, ...printed };
  }

  pipeline(): Pipeline {
    const negate = this.is("!");
    if (negate) this.advance();
    const commands = [this.command()];
    while (this.is("|")) {
      this.advance();
      this.newlines();
      commands.push(this.command());
    }
    return { commands, negate };
  }

  command(): Command {
    if (++this.nesting + this.lexer.depth > 64) this.error("Syntax nesting exceeds 64");
    const line = this.lexer.lineAt(this.current.offset);
    this.openCommands.push({ name: this.current.value, line });
    try {
      const command = this.commandInner();
      return { ...command, line: command.line ?? line };
    } finally { this.nesting--; this.openCommands.pop(); }
  }

  commandInner(): Command {
    let command: Command;
    if (this.is("(") && this.lexer.source.startsWith("((", this.current.offset)) {
      const start = this.current.offset + 2;
      const end = arithmeticEnd(this.lexer.source, start);
      const source = this.lexer.source.slice(start, end);
      command = { kind: "arithmetic", expression: prepareArithmetic(source), source, redirects: [] };
      this.lexer.position = end + 2;
      this.lookahead = undefined;
      this.current = this.lexer.next();
    } else if (this.is("(") || this.is("{")) {
      const subshell = this.is("(");
      this.advance();
      const body = this.script(new Set([subshell ? ")" : "}"]));
      if (!body.lists.length) this.error("Empty compound command");
      this.expect(subshell ? ")" : "}");
      command = { kind: subshell ? "subshell" : "group", body, redirects: [] };
    } else if (this.is("if")) {
      this.advance();
      const branches: { condition: Script; body: Script }[] = [];
      while (true) {
        const condition = this.nonemptyScript(new Set(["then"]));
        this.expect("then");
        const body = this.nonemptyScript(new Set(["elif", "else", "fi"]));
        branches.push({ condition, body });
        if (!this.is("elif")) break;
        this.advance();
      }
      let otherwise: Script | undefined;
      if (this.is("else")) {
        this.advance();
        otherwise = this.nonemptyScript(new Set(["fi"]));
      }
      this.expect("fi");
      command = { kind: "if", branches, ...(otherwise ? { otherwise } : {}), redirects: [] };
    } else if (this.is("case")) {
      this.advance();
      if (!this.current.word) this.error("Expected case subject");
      const subject = this.advance().word!;
      this.newlines();
      this.expect("in");
      this.newlines();
      const clauses: CaseClause[] = [];
      while (!this.is("esac")) {
        if (this.is("(")) this.advance();
        const patterns: Word[] = [];
        while (true) {
          if (!this.current.word) this.error("Expected case pattern");
          patterns.push(this.advance().word!);
          if (!this.is("|")) break;
          this.advance();
        }
        this.expect(")");
        const body = this.script(new Set([";;", ";&", ";;&", "esac"]));
        if (![";;", ";&", ";;&", "esac"].includes(this.current.value)) this.error("Expected case terminator");
        const terminator = this.current.value as CaseClause["terminator"];
        clauses.push({ patterns, body, terminator });
        if (terminator === "esac") break;
        this.advance();
        this.newlines();
      }
      this.expect("esac");
      command = { kind: "case", subject, clauses, redirects: [] };
    } else if (this.is("while") || this.is("until")) {
      const kind = this.advance().value as "while" | "until";
      const condition = this.nonemptyScript(new Set(["do"]));
      this.expect("do");
      const body = this.nonemptyScript(new Set(["done"]));
      this.expect("done");
      command = { kind, condition, body, redirects: [] };
    } else if (this.is("for")) {
      this.advance();
      const name = this.advance().value;
      if (!/^[a-zA-Z_][a-zA-Z_0-9]*$/u.test(name)) this.error("Invalid for variable");
      this.newlines();
      let words: Word[] | undefined;
      if (this.is("in")) {
        this.advance();
        words = [];
        while (this.current.kind === "word") words.push(this.advance().word!);
      }
      if (this.is(";") || this.is("\n")) this.advance();
      else if (words) this.error("Expected for separator");
      this.newlines();
      this.expect("do");
      const body = this.nonemptyScript(new Set(["done"]));
      this.expect("done");
      command = { kind: "for", name, ...(words ? { words } : {}), body, redirects: [] };
    } else if (this.current.kind === "word" && this.peek().value === "(") {
      const name = this.advance().value;
      if (!/^[a-zA-Z_][a-zA-Z_0-9]*$/u.test(name)) this.error("Invalid function name");
      this.expect("(");
      this.expect(")");
      this.newlines();
      if (!["{", "(", "if", "case", "while", "until", "for"].includes(this.current.value)) this.error("Expected function body");
      command = { kind: "function", name, body: this.command(), redirects: [] };
    } else {
      if (["!", "then", "else", "elif", "fi", "do", "done", "}", "case", "esac", "select", "function", "[[", "]]"].includes(this.current.value)) this.error(`Unexpected or unsupported keyword ${this.current.value}`);
      const words: Word[] = [];
      const redirects: Redirect[] = [];
      let line: number | undefined;
      while (true) {
        const wordLine = this.lexer.lineAt(Math.max(this.current.offset, this.current.end - 1));
        const redirect = this.redirect();
        if (redirect) { line ??= redirect.line; redirects.push(redirect); }
        else if (this.current.kind === "word") { line ??= wordLine; words.push(this.advance().word!); }
        else break;
      }
      if (!words.length && !redirects.length) this.error("Expected command");
      return { kind: "simple", words, redirects, ...(line === undefined ? {} : { line }) };
    }
    let redirect: Redirect | undefined;
    while ((redirect = this.redirect())) command.redirects.push(redirect);
    return command;
  }

  nonemptyScript(stops: Set<string>): Script {
    const script = this.script(stops);
    if (!script.lists.length) this.error("Expected nonempty compound list");
    return script;
  }

  redirect(): Redirect | undefined {
    let descriptor: number | undefined;
    if (this.current.kind === "word" && /^\d+$/u.test(this.current.value)) {
      const next = this.peek();
      if (/^(?:>|>>|<|<<|<<-|<<<|>&|<&|>\|)$/u.test(next.value) && this.current.end === next.offset) descriptor = Number(this.advance().value);
    }
    if (!/^(?:>|>>|<|<<|<<-|<<<|>&|<&|>\|)$/u.test(this.current.value) || this.current.kind !== "operator") return undefined;
    const operator = this.advance().value;
    descriptor ??= operator.startsWith("<") ? 0 : 1;
    if (!Number.isSafeInteger(descriptor) || descriptor > 255) this.error("File descriptor must be between 0 and 255");
    if (!this.current.word) this.error("Expected redirect target");
    const target = this.advance();
    return { descriptor, operator, target: target.word!, line: this.lexer.lineAt(Math.max(target.offset, target.end - 1)), ...((operator === "<&" || operator === ">&") && this.lexer.source[target.end - 1] === "-" ? { move: true } : {}), ...(target.document ? { document: target.document } : {}) };
  }
}

export function parseShell(source: string, depth = 0): Script {
  const warnings: string[] = [];
  const script = parseSource(source, depth, warnings);
  return { ...script, ...(warnings.length ? { warnings } : {}) };
}

export function* hereDocumentWords(document: HereDocument, line: number, byteLocale: boolean, warnings: string[]): Generator<Word> {
  if (document.quoted) yield { offset: document.offset, parts: [{ kind: "text", value: document.body, quoted: true }] };
  else yield* new Lexer(document.body, document.depth, warnings, line - 1, byteLocale, line).documentWords();
}

export function parseShellUnit(source: string, position = 0, byteLocale = false): { script: Script; next: number } {
  const warnings: string[] = [];
  const parser = new Parser(source, 0, warnings, 0, position, byteLocale);
  const script = parser.script(new Set(), true);
  const next = parser.current.end;
  const nul = source.indexOf("\0", position);
  if (nul >= 0 && nul < next) throw new ShellSyntaxError("NUL bytes are not valid shell source", nul);
  return { script: { ...script, ...(warnings.length ? { warnings } : {}) }, next };
}

export function parseShellInputUnit(source: string, byteLocale = false): { script: Script; next: number } | undefined {
  const warnings: string[] = [];
  try {
    const parser = new Parser(source, 0, warnings, 0, 0, byteLocale, true);
    const script = parser.script(new Set(), true);
    return { script: { ...script, ...(warnings.length ? { warnings } : {}) }, next: parser.current.end };
  } catch (error) {
    if (error instanceof IncompleteShellInput) return undefined;
    if (error instanceof ShellSyntaxError && (/^Unterminated|^Trailing escape/u.test(error.reason) || (error.offset >= source.length && !/Unsupported|unsupported|nesting|exceeds/u.test(error.reason)))) return undefined;
    throw error;
  }
}

function parseSource(source: string, depth: number, warnings: string[], lineOffset = 0, byteLocale = false): Script {
  const parser = new Parser(source, depth, warnings, lineOffset, undefined, byteLocale);
  const script = parser.script();
  if (parser.current.kind !== "end") parser.error("Unexpected token");
  return script;
}

import type { ByteSource } from "../contracts/index.js";
import { Budget, interruptible } from "./runtime.js";

class InputCursor {
  readonly #iterator: AsyncIterator<Uint8Array>;
  remainder: Uint8Array | undefined;
  #read: Promise<IteratorResult<Uint8Array>> | undefined;
  #readSettled = false;
  #turn = Promise.resolve();
  #returned: Promise<void> | undefined;
  #ended = false;
  #closed = false;

  constructor(source: ByteSource) {
    this.#iterator = source[Symbol.asyncIterator]();
  }

  async consume<Value>(signal: AbortSignal, operation: () => Promise<Value>): Promise<Value> {
    signal.throwIfAborted();
    const previous = this.#turn;
    let release!: () => void;
    const completed = new Promise<void>((resolve) => { release = resolve; });
    this.#turn = previous.then(() => completed);
    try {
      await interruptible(previous, signal);
      signal.throwIfAborted();
      return await operation();
    } finally { release(); }
  }

  async take(signal: AbortSignal): Promise<IteratorResult<Uint8Array>> {
    signal.throwIfAborted();
    if (this.remainder) {
      const value = this.remainder;
      this.remainder = undefined;
      return { value, done: false };
    }
    if (this.#ended || this.#closed) return { value: undefined, done: true };
    if (!this.#read) {
      this.#readSettled = false;
      this.#read = Promise.resolve().then(() => this.#closed ? { value: undefined, done: true as const } : this.#iterator.next()).then((result) => {
        if (result.done) return { value: undefined, done: true };
        if (!(result.value instanceof Uint8Array)) throw new TypeError("Shell stdin must yield Uint8Array");
        return { value: new Uint8Array(result.value), done: false };
      });
      void this.#read.then(() => { this.#readSettled = true; }, () => { this.#readSettled = true; });
    }
    try {
      const result = await interruptible(this.#read, signal);
      signal.throwIfAborted();
      this.#read = undefined;
      if (result.done) this.#ended = true;
      return result;
    } catch (error) {
      if (!signal.aborted) { this.#read = undefined; this.#closed = true; }
      throw error;
    }
  }

  async close(signal: AbortSignal): Promise<void> {
    if (this.#ended) { signal.throwIfAborted(); return; }
    this.#closed = true;
    this.remainder = undefined;
    const pendingRead = this.#read !== undefined && !this.#readSettled;
    this.#returned ??= Promise.resolve().then(() => this.#iterator.return?.()).then(() => undefined, () => undefined);
    if (!pendingRead) await interruptible(this.#returned, signal);
    signal.throwIfAborted();
  }
}

export class ShellInput implements ByteSource {
  readonly #cursor: InputCursor;
  readonly #owned: boolean;
  readonly #lifetime = new AbortController();
  readonly #cleanupSignal: AbortSignal;
  readonly signal: AbortSignal;
  #closing: Promise<void> | undefined;

  constructor(source: ByteSource, readonly budget: Budget, signal = budget.signal) {
    this.#owned = !(source instanceof ShellInput);
    this.#cursor = source instanceof ShellInput ? source.#cursor : new InputCursor(source);
    this.#cleanupSignal = signal;
    this.signal = AbortSignal.any([signal, this.#lifetime.signal]);
  }

  next(): Promise<IteratorResult<Uint8Array>> {
    return this.#cursor.consume(this.signal, () => this.#cursor.take(this.signal));
  }

  [Symbol.asyncIterator](): AsyncIterableIterator<Uint8Array> {
    return { next: () => this.next(), [Symbol.asyncIterator]() { return this; } };
  }

  sourceLine(): Promise<Uint8Array | undefined> {
    return this.#cursor.consume(this.signal, async () => {
      const chunks: Uint8Array[] = [];
      let length = 0;
      let pulls = 0;
      while (true) {
        if (++pulls % 128 === 0) await interruptible(new Promise<void>(resolve => setImmediate(resolve)), this.signal);
        const result = await this.#cursor.take(this.signal);
        if (result.done) {
          if (!length) return undefined;
          break;
        }
        const newline = result.value.indexOf(10);
        const end = newline < 0 ? result.value.length : newline + 1;
        if (end < result.value.length) this.#cursor.remainder = result.value.subarray(end);
        this.budget.source(end);
        if (end) chunks.push(result.value.subarray(0, end));
        length += end;
        if (newline >= 0) break;
      }
      const bytes = new Uint8Array(length);
      let offset = 0;
      for (const chunk of chunks) { bytes.set(chunk, offset); offset += chunk.length; }
      return bytes;
    });
  }

  line(raw: boolean, options?: { count?: number; delimiter?: number; byteCount?: boolean; exact?: boolean }): Promise<{ value: string; escaped: ReadonlySet<number>; terminated: boolean }> {
    return this.#cursor.consume(this.signal, () => options ? this.readBounded(raw, options) : this.readLine(raw));
  }

  private async readBounded(raw: boolean, options: { count?: number; delimiter?: number; byteCount?: boolean; exact?: boolean }): Promise<{ value: string; escaped: ReadonlySet<number>; terminated: boolean }> {
    const characters: string[] = [];
    const escaped = new Set<number>();
    const decoder = new TextDecoder("utf-8", { fatal: true });
    const delimiter = options.delimiter ?? 10;
    let chunk: Uint8Array = new Uint8Array();
    let offset = 0;
    let length = 0;
    let escaping = false;
    let escapedCharacter = false;
    let units = 0;
    let pulls = 0;
    let terminated = options.count === 0;
    try {
      while (!terminated) {
        if (offset === chunk.length) {
          if (++pulls % 128 === 0) await interruptible(new Promise<void>(resolve => setImmediate(resolve)), this.signal);
          const result = await this.#cursor.take(this.signal);
          if (result.done) {
            break;
          }
          chunk = result.value;
          offset = 0;
          if (!chunk.length) continue;
        }
        const byte = chunk[offset++]!;
        if (!options.exact && !escaping && byte === delimiter) { terminated = true; break; }
        if (++length > this.budget.limits.maxOutputBytes) this.budget.fail("maxOutputBytes");
        if (length % 1024 === 0) {
          await interruptible(new Promise<void>((resolve) => setImmediate(resolve)), this.signal);
          this.signal.throwIfAborted();
        }
        if (byte === 0) continue;
        if (!raw && !escaping && byte === 92) { escaping = true; continue; }
        if (escaping) {
          escaping = false;
          if (byte === 10) continue;
          escapedCharacter = true;
        }
        const decoded = decoder.decode(Uint8Array.of(byte), { stream: true });
        for (const character of decoded) {
          if (escapedCharacter) {
            escapedCharacter = false;
            escaped.add(characters.length);
          }
          characters.push(character);
        }
        units += options.byteCount ? 1 : Array.from(decoded).length;
        if (units === options.count) terminated = true;
      }
      decoder.decode();
      return { value: characters.join(""), escaped, terminated };
    } catch (error) {
      if (error instanceof TypeError && error.message.includes("encoded data")) throw new Error("read: unsupported non-UTF-8 text boundary");
      throw error;
    } finally {
      if (offset < chunk.length) this.#cursor.remainder = chunk.subarray(offset);
    }
  }

  private async readLine(raw: boolean): Promise<{ value: string; escaped: ReadonlySet<number>; terminated: boolean }> {
    const chunks: Uint8Array[] = [];
    let length = 0;
    let terminated = false;
    while (true) {
      const result = await this.#cursor.take(this.signal);
      if (result.done) break;
      const newline = result.value.indexOf(10);
      const chunk = newline < 0 ? result.value : result.value.subarray(0, newline);
      if (chunk.byteLength > this.budget.limits.maxOutputBytes - length) this.budget.fail("maxOutputBytes");
      chunks.push(new Uint8Array(chunk));
      length += chunk.byteLength;
      if (newline >= 0) {
        if (newline + 1 < result.value.length) this.#cursor.remainder = result.value.subarray(newline + 1);
        let slashes = 0;
        if (!raw) {
          for (let chunkIndex = chunks.length - 1; chunkIndex >= 0; chunkIndex--) {
            const bytes = chunks[chunkIndex]!;
            let offset = bytes.length - 1;
            while (offset >= 0 && bytes[offset] === 92) { slashes++; offset--; }
            if (offset >= 0) break;
          }
        }
        if (slashes % 2 === 1) {
          while (chunks.at(-1)?.length === 0) chunks.pop();
          chunks[chunks.length - 1] = chunks.at(-1)!.subarray(0, -1);
          length--;
        } else { terminated = true; break; }
      }
    }
    const bytes = new Uint8Array(length);
    let offset = 0;
    for (const chunk of chunks) { bytes.set(chunk, offset); offset += chunk.length; }
    const value = new TextDecoder().decode(bytes).replace(/\0/gu, "");
    const escaped = new Set<number>();
    if (raw) return { value, escaped, terminated };
    const characters = Array.from(value);
    const unescaped: string[] = [];
    for (let index = 0; index < characters.length; index++) {
      if (characters[index] === "\\") {
        if (++index === characters.length) break;
        escaped.add(unescaped.length);
      }
      unescaped.push(characters[index]!);
    }
    return { value: unescaped.join(""), escaped, terminated };
  }

  close(): Promise<void> {
    if (!this.#closing) {
      this.#lifetime.abort(new Error("Shell input view closed"));
      this.#closing = this.#owned ? this.#cursor.close(this.#cleanupSignal) : Promise.resolve();
    }
    return this.#closing;
  }
}

export function byteLocale(variables: Readonly<Record<string, string>>): boolean {
  const locale = variables.LC_ALL || variables.LC_CTYPE || variables.LANG;
  return locale === "C" || locale === "POSIX";
}

import type { InvocationCleanup } from "../contracts/command.js";

export const invocationScope = Symbol("invocation cleanup scope");

export class InvocationScope {
  readonly #children = new Set<InvocationScope>();
  readonly #callbacks: InvocationCleanup[] = [];
  readonly #controller = new AbortController();
  #closed = false;
  #drain: Promise<void> | undefined;

  constructor(
    readonly callerSignal?: AbortSignal,
    readonly failures: unknown[] = [],
    readonly parent?: InvocationScope,
  ) {}

  get signal(): AbortSignal { return this.#controller.signal; }

  assertOpen(): void {
    this.callerSignal?.throwIfAborted();
    if (this.#closed) throw this.signal.reason;
    this.parent?.assertOpen();
  }

  child(): InvocationScope {
    this.assertOpen();
    const child = new InvocationScope(this.callerSignal, this.failures, this);
    this.#children.add(child);
    return child;
  }

  register(cleanup: InvocationCleanup): void {
    this.assertOpen();
    if (typeof cleanup !== "function") throw new TypeError("Cleanup must be callable");
    this.#callbacks.push(cleanup);
  }

  #seal(): void {
    if (this.#closed) return;
    this.#closed = true;
    for (const child of this.#children) child.#seal();
    this.#controller.abort(new Error("Invocation is closed"));
  }

  close(): Promise<void> {
    if (!this.#drain) {
      this.#drain = Promise.resolve().then(async () => {
        await Promise.all([
          ...this.#callbacks.map(async (cleanup) => {
            try { await cleanup(); } catch (error) { this.failures.push(error); }
          }),
          ...[...this.#children].map((child) => child.close()),
        ]);
      });
      this.#seal();
    }
    return this.#drain;
  }
}

export function throwCleanupFailures(failures: readonly unknown[]): void {
  if (failures.length === 1) throw failures[0];
  if (failures.length) throw new AggregateError(failures, "Invocation cleanup failed");
}

import { ShellSyntaxError } from "./types.js";

export type Arithmetic = (
  | { kind: "literal"; value: bigint }
  | { kind: "name"; name: string }
  | { kind: "unary"; operator: string; operand: Arithmetic; postfix: boolean }
  | { kind: "binary"; operator: string; left: Arithmetic; right: Arithmetic }
  | { kind: "conditional"; condition: Arithmetic; yes: Arithmetic; no: Arithmetic }
) & { start?: number };

export interface ArithmeticProgram {
  readonly source: string;
  readonly tree?: Arithmetic;
  readonly error?: ShellSyntaxError;
}

class ArithmeticFailure extends Error {
  constructor(message: string, readonly offset: number) { super(message); }
}

export function prepareArithmetic(source: string): ArithmeticProgram {
  try { return { source, tree: parseArithmetic(source) }; }
  catch (error) {
    if (!(error instanceof ShellSyntaxError) || /nesting/u.test(error.reason)) throw error;
    return { source, error };
  }
}

const precedence: Record<string, number> = {
  ",": 1, "=": 2, "+=": 2, "-=": 2, "*=": 2, "/=": 2, "%=": 2,
  "<<=": 2, ">>=": 2, "&=": 2, "^=": 2, "|=": 2,
  "?": 3, "||": 4, "&&": 5, "|": 6, "^": 7, "&": 8,
  "==": 9, "!=": 9, "<": 10, "<=": 10, ">": 10, ">=": 10,
  "<<": 11, ">>": 11, "+": 12, "-": 12, "*": 13, "/": 13, "%": 13, "**": 14,
};

function integer(text: string): bigint {
  if (/^0[xX][\da-fA-F]+$/u.test(text)) return BigInt(text);
  if (/^0[0-7]+$/u.test(text)) return BigInt(`0o${text.slice(1)}`);
  if (/^0\d+$/u.test(text)) throw new Error("Invalid octal constant");
  if (/^\d+$/u.test(text)) return BigInt(text);
  const match = /^(\d+)#([\da-zA-Z@_]+)$/u.exec(text);
  if (!match) throw new Error("Invalid arithmetic constant");
  const base = Number(match[1]);
  if (base < 2 || base > 64) throw new Error("Invalid arithmetic base");
  let value = 0n;
  for (const character of match[2]!) {
    const digit = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ@_".indexOf(base <= 36 ? character.toLowerCase() : character);
    if (digit >= base || digit < 0) throw new Error("Digit exceeds arithmetic base");
    value = value * BigInt(base) + BigInt(digit);
  }
  return value;
}

export function parseArithmetic(source: string, offset = 0): Arithmetic {
  const tokens: { value: string; offset: number }[] = [];
  let position = 0;
  while (position < source.length) {
    if (/\s/u.test(source[position]!)) { position++; continue; }
    const value = /^(?:\d+#[\da-zA-Z@_]+|0[xX][\da-fA-F]+|\d+|[a-zA-Z_][a-zA-Z_0-9]*|<<=|>>=|\*\*|\+\+|--|&&|\|\||<<|>>|[+*/%&^|!<>=-]=|[()+*/%~!<>=&^|?:,\-])/u.exec(source.slice(position))?.[0];
    if (!value) throw new ShellSyntaxError("Unsupported arithmetic token", offset + position);
    tokens.push({ value, offset: offset + position });
    position += value.length;
  }
  let cursor = 0;
  let depth = 0;
  const current = () => tokens[cursor]?.value ?? "";
  const error = (message: string): never => { throw new ShellSyntaxError(message, tokens[cursor]?.offset ?? offset + source.length); };
  const expression = (minimum = 1): Arithmetic => {
    if (++depth > 64) error("Arithmetic nesting exceeds 64");
    let left: Arithmetic;
    const start = tokens[cursor]?.offset ?? offset + source.length;
    const token = current();
    cursor++;
    if (["+", "-", "!", "~", "++", "--"].includes(token)) {
      const operand = expression(15);
      if (["++", "--"].includes(token) && operand.kind !== "name") error("Arithmetic assignment requires a variable");
      left = { kind: "unary", operator: token, operand, postfix: false };
    } else if (token === "(") {
      left = expression();
      if (current() !== ")") error("Unclosed arithmetic parenthesis");
      cursor++;
    } else if (/^[a-zA-Z_]/u.test(token)) left = { kind: "name", name: token };
    else {
      try { left = { kind: "literal", value: BigInt.asIntN(64, integer(token)) }; }
      catch { error("Invalid arithmetic operand"); }
    }
    left!.start = start;
    while (true) {
      const operator = current();
      if (operator === "++" || operator === "--") {
        if (left!.kind !== "name") error("Arithmetic assignment requires a variable");
        cursor++;
        left = { kind: "unary", operator, operand: left!, postfix: true, start };
        continue;
      }
      const priority = Object.hasOwn(precedence, operator) ? precedence[operator]! : 0;
      if (priority < minimum || priority === 0) break;
      cursor++;
      if (operator === "?") {
        const yes = expression();
        if (current() !== ":") error("Expected arithmetic colon");
        cursor++;
        left = { kind: "conditional", condition: left!, yes, no: expression(3), start };
      } else {
        const assignment = priority === 2;
        if (assignment && left!.kind !== "name") error("Arithmetic assignment requires a variable");
        const right = expression(priority + (assignment || operator === "**" ? 0 : 1));
        left = { kind: "binary", operator, left: left!, right, start };
      }
    }
    depth--;
    return left!;
  };
  if (!tokens.length) return { kind: "literal", value: 0n };
  const tree = expression();
  if (cursor < tokens.length) error("Unexpected arithmetic token");
  return tree;
}

export function arithmeticEnd(source: string, start: number): number {
  let depth = 0;
  for (let position = start; position < source.length; position++) {
    const character = source[position];
    if (character === "(") depth++;
    if (character === ")") {
      if (depth === 0 && source[position + 1] === ")") return position;
      if (--depth < 0) break;
    }
  }
  throw new ShellSyntaxError("Unterminated arithmetic expression", start);
}

export function evaluateArithmetic(program: ArithmeticProgram, variables: Record<string, string>): bigint {
  const visiting = new Set<string>();
  let steps = 0;
  const binary = (operator: string, left: bigint, right: bigint, offset: number): bigint => {
    switch (operator) {
      case "+": return left + right;
      case "-": return left - right;
      case "*": return left * right;
      case "/": if (right === 0n) throw new ArithmeticFailure("division by 0", offset); return left / right;
      case "%": if (right === 0n) throw new ArithmeticFailure("division by 0", offset); return left % right;
      case "**": {
        if (right < 0n) throw new ArithmeticFailure("exponent less than 0", offset);
        let result = 1n;
        let base = left;
        let exponent = right;
        while (exponent) {
          if (exponent & 1n) result = BigInt.asIntN(64, result * base);
          exponent >>= 1n;
          base = BigInt.asIntN(64, base * base);
        }
        return result;
      }
      case "<<": return left << (right & 63n);
      case ">>": return left >> (right & 63n);
      case "&": return left & right;
      case "|": return left | right;
      case "^": return left ^ right;
      case "==": return BigInt(left === right);
      case "!=": return BigInt(left !== right);
      case "<": return BigInt(left < right);
      case "<=": return BigInt(left <= right);
      case ">": return BigInt(left > right);
      case ">=": return BigInt(left >= right);
      default: throw new Error(`Unsupported arithmetic operator ${operator}`);
    }
  };
  const evaluate = (node: Arithmetic): bigint => {
    if (++steps > 10_000) throw new Error("Arithmetic operation limit exceeded");
    let value: bigint;
    if (node.kind === "literal") return node.value;
    if (node.kind === "name") {
      if (visiting.has(node.name) || visiting.size >= 64) throw new Error("Arithmetic variable recursion");
      visiting.add(node.name);
      try { return evaluate(parseArithmetic(variables[node.name] ?? "0")); }
      finally { visiting.delete(node.name); }
    }
    if (node.kind === "conditional") return evaluate(evaluate(node.condition) ? node.yes : node.no);
    if (node.kind === "unary") {
      const operand = evaluate(node.operand);
      if (node.operator === "+") value = operand;
      else if (node.operator === "-") value = -operand;
      else if (node.operator === "!") value = BigInt(!operand);
      else if (node.operator === "~") value = ~operand;
      else {
        value = BigInt.asIntN(64, operand + (node.operator === "++" ? 1n : -1n));
        variables[(node.operand as Extract<Arithmetic, { kind: "name" }>).name] = String(value);
        if (node.postfix) value = operand;
      }
    } else {
      if (node.operator === "=") value = evaluate(node.right);
      else {
        const left = evaluate(node.left);
        if (node.operator === "&&") return left ? BigInt(evaluate(node.right) !== 0n) : 0n;
        if (node.operator === "||") return left ? 1n : BigInt(evaluate(node.right) !== 0n);
        if (node.operator === ",") return evaluate(node.right);
        value = binary(precedence[node.operator] === 2 ? node.operator.slice(0, -1) : node.operator, left, evaluate(node.right), node.right.start ?? 0);
      }
      if (precedence[node.operator] === 2) variables[(node.left as Extract<Arithmetic, { kind: "name" }>).name] = String(BigInt.asIntN(64, value));
    }
    return BigInt.asIntN(64, value);
  };
  try {
    if (program.error) throw program.error;
    return evaluate(program.tree!);
  } catch (error) {
    if (error instanceof ArithmeticFailure) throw new Error(`${program.source.trimStart()}: ${error.message} (error token is "${program.source.slice(error.offset)}")`);
    if (error instanceof ShellSyntaxError) {
      const offset = error.offset >= program.source.trimEnd().length ? Math.max(0, program.source.trimEnd().length - 1) : error.offset;
      const reason = error.reason === "Invalid arithmetic operand" ? "arithmetic syntax error: operand expected" : "arithmetic syntax error in expression";
      throw new Error(`${program.source.trimStart()}: ${reason} (error token is "${program.source.slice(offset)}")`);
    }
    throw error;
  }
}

